/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A56 staging · exact frozen manifest insurer–introductory (80 lemmas). */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[c],mistakes:[m],quiz:qs});
P('insurer','insurer 由 insure 加表示施事者的 -er 构成，指承诺在约定损失发生时赔付的一方或保险公司。',C('insurer.s1','保险合同','The insurer agreed to cover repair costs after reviewing the damage report and confirming that the policy applied.','保险公司审阅损坏报告并确认保单适用后，同意承担维修费用。','The insurer agreed to cover repair costs / after reviewing the damage report / and confirming / that the policy applied.','insurer 指承担约定赔付责任的一方；after 引出确认理赔前的审查。','保险公司依合同承担维修费用，符合 s1。'),M('The policyholder was called the insurer even though the company alone had agreed to pay for covered losses.','The company was called the insurer because it agreed to pay covered losses.','投保人不是承诺赔付的一方；赔付责任属于保险人。'),[Q('insurer',1,1,'An insurer is?','the party that agrees to pay for a specified covered loss','the person who always pays premiums only','a government that indicts someone','insurer 指保险公司或承担赔付的一方。'),Q('insurer',2,1,'If a covered loss occurs, the insurer may?','pay according to the policy','automatically become the policyholder','refuse every claim regardless of terms','保险人按合同对承保损失赔付。'),Q('insurer',3,1,'The suffix -er in insurer identifies?','a person or company that insures','a condition of being insured','an adjective describing a policy','-er 表示提供保险的一方。'),Q('insurer',4,1,'Which role is the insurer?','the company that agreed to cover specified damage','the customer buying a policy','the repair shop that fixed the damage','保险公司是约定赔付方。')]);
P('insurgence','insurgence 源自拉丁语 insurgere（起身反抗），指针对政府或其他权威的暴力起事。',C('insurgence.s1','历史报道','The documentary describes the insurgence against the colonial administration and explains how civilians were affected.','纪录片介绍了针对殖民当局的暴动，并说明平民受到的影响。','The documentary describes the insurgence / against the colonial administration / and explains / how civilians were affected.','insurgence 是表示暴力起事的名词；against 引出反抗对象。','针对当局的武装起事符合 s1。'),M('The report called a peaceful election and orderly handover of power an insurgence.','The report called the violent rising against the authorities an insurgence.','和平选举和有序交接不是暴力反抗起事。'),[Q('insurgence',1,1,'An insurgence is?','a violent rising against a government or authority','a peaceful agreement between officials','a normal insurance payment','insurgence 指暴动或叛乱。'),Q('insurgence',2,1,'An insurgence may be directed against?','a government or other authority','an unrelated intercity train','a person’s digestive system','该词指反抗权威的暴力起事。'),Q('insurgence',3,1,'Which event fits insurgence?','an armed rising against the ruling authority','a routine local election with peaceful transfer','a private conversation between neighbors','暴力反抗当局符合该义。'),Q('insurgence',4,1,'Insurgence is a?','noun for a violent uprising','verb meaning to insure property','adverb meaning intensely','insurgence 是名词。')]);
P('insurmountable','insurmountable 由否定前缀 in- 与 surmountable 构成，表示无法成功处理或克服的。',C('insurmountable.s1','工程规划','The team first thought the access problem was insurmountable, but a temporary ramp made the site usable.','团队起初认为通行问题无法克服，但一条临时坡道让场地变得可用。','The team first thought the access problem / was insurmountable / but a temporary ramp / made the site usable.','insurmountable 修饰 problem，表示无法克服；but 呈现解决办法改变了最初判断。','团队起初认为问题无法解决，符合 s1 的含义。'),M('The obstacle was called insurmountable even though the team crossed it easily with the first simple solution.','The obstacle was manageable because the team crossed it easily.','轻易解决的障碍不是 insurmountable。'),[Q('insurmountable',1,1,'An insurmountable obstacle is?','impossible to deal with successfully or get over','easy to overcome','something that must be interred','insurmountable 指无法克服的。'),Q('insurmountable',2,1,'A problem once thought insurmountable may be?','solved by a new approach','impossible to approach in any way','a type of interaction','改变方法可能使原问题得到解决。'),Q('insurmountable',3,1,'The prefix in- in insurmountable means?','not','between','very strongly','否定前缀构成“无法克服”。'),Q('insurmountable',4,1,'A close opposite of insurmountable is?','surmountable','unbeatable','impossible','surmountable 表示可以克服的。')]);
P('intaglio','intaglio 源自意大利语 intagliare（雕刻），可指图案刻入表面形成的凹雕或由此制成的版画，也可作动词表示凹刻。',C('intaglio.s1','工艺品鉴赏','The museum displayed an intaglio seal whose tiny design was carved below the stone’s surface.','博物馆展出了一枚凹雕印章，细小图案刻在石头表面以下。','The museum displayed an intaglio seal / whose tiny design / was carved below the stone’s surface.','intaglio 在此作名词，指凹雕作品；whose 从句说明图案位于表面下方。','凹刻图案低于材料表面，符合 s1。'),M('The catalog described the raised design standing above the stone as an intaglio engraving.','The catalog described the recessed design carved below the stone’s surface as an intaglio.','凸起高于表面的图案不是凹雕。'),[Q('intaglio',1,1,'An intaglio design is carved?','into a surface so it sits below the surface','so it projects far above the surface','only as a sound recording','intaglio 的图案低于材料表面。'),Q('intaglio',2,2,'To intaglio a surface is to?','carve a design into it','raise a design above it','intercede on someone’s behalf','动词义指作凹雕。'),Q('intaglio',3,1,'An intaglio print may be made from?','a plate with an incised design','a blank sheet with no mark','a raised sculpture only','凹版可用于制作版画。'),Q('intaglio',4,1,'Which item is an intaglio?','a seal with its image cut below the surface','a badge with a raised image','a flat sheet with no design','刻入表面形成的凹图案符合该义。')]);
P('integration','integration 可指把各部分合并成一个协作整体，也可指不同群体平等地共同生活和工作。',C('integration.s1','软件系统','The integration of the payment and inventory systems lets staff see stock changes as orders are processed.','支付系统与库存系统整合后，员工可以在处理订单时查看库存变化。','The integration of the payment and inventory systems / lets staff see stock changes / as orders are processed.','integration of A and B 表示系统整合；lets 引出整合带来的功能。','两个系统协作成为整体，符合 s1。'),M('The company called the two disconnected systems integration even though they never exchanged data or worked together.','The company called the systems separate because they never exchanged data.','完全不连接也不协作不是整合。'),[Q('integration',1,1,'System integration is?','combining parts so they work as one','keeping every part isolated','a person who works between two cities','s1 指各部分整合。'),Q('integration',2,2,'Social integration means?','people from different groups live and work together equally','groups remain permanently excluded from one another','a device measures interference','s2 指社会群体平等融合。'),Q('integration',3,1,'The integration of payment and inventory software allows?','the systems to share useful information','each system to remain disconnected','the company to become an insurer','整合让系统之间协作。'),Q('integration',4,2,'Which policy promotes social integration?','one that supports equal participation across groups','one that bars one group from public life','one that interbreeds different plants','平等参与有助于社会融合。')]);
P('integrative','integrative 由 integrate 加 -ive 构成，形容能够把分开的部分联合起来的。',C('integrative.s1','教学设计','The integrative course links biology, statistics, and writing through a single research project.','这门综合课程通过一个研究项目把生物学、统计学和写作联系起来。','The integrative course links biology, statistics, and writing / through a single research project.','integrative 修饰 course，表示整合多个领域；through 引出课程采用的方式。','课程把不同知识领域联合起来，符合 s1。'),M('The course was described as integrative even though its subjects were kept completely separate and never connected.','The course was described as separate because its subjects were never connected.','各领域完全隔离而不发生联系，不符合 integrative。'),[Q('integrative',1,1,'An integrative approach?','unites separate elements','keeps every element isolated','is impossible to overcome','integrative 指整合性的。'),Q('integrative',2,1,'An integrative course might connect?','several fields in one project','unrelated lessons with no shared work','only one unchanging subject','综合课程会把多个领域联系起来。'),Q('integrative',3,1,'Integrative is related to the verb?','integrate','inter','insure','integrative 与 integrate 同词族。'),Q('integrative',4,1,'Which phrase is natural?','an integrative framework','an integrative between framework','integrative to separate pieces','该形容词修饰能整合内容的 framework。')]);
P('intellectually','intellectually 由 intellectual 加副词后缀 -ly 构成，表示在思考和理解方面。',C('intellectually.s1','阅读选择','The novel was intellectually demanding because its narrator changed viewpoints and questioned the reliability of memory.','这部小说在智力上颇具挑战，因为叙述者不断切换视角，并质疑记忆是否可靠。','The novel was intellectually demanding / because its narrator changed viewpoints / and questioned the reliability of memory.','intellectually 修饰 demanding，说明挑战涉及思考和理解；because 给出原因。','读者需要分析视角和记忆，符合 s1。'),M('The puzzle was intellectually challenging because it required no thought, attention, or understanding at all.','The puzzle was not intellectually challenging because it required no thought.','无需思考理解就不构成智力挑战。'),[Q('intellectually',1,1,'Intellectually means?','with regard to thinking and understanding','with regard to a person’s physical height','in a secret way','intellectually 指在智力或理解方面。'),Q('intellectually',2,1,'An intellectually demanding novel may require?','analyzing ideas and points of view','only counting pages','no attention or thought','复杂观点需要读者思考。'),Q('intellectually',3,1,'Which phrase is natural?','intellectually curious','intellectually a traffic signal','intellectually between two cities','intellectually 可修饰 curious。'),Q('intellectually',4,1,'The related adjective is?','intellectual','interactive','intaglio','intellectually 来自 intellectual。')]);
P('intelligently','intelligently 由 intelligent 加 -ly 构成，表示有理解力并运用良好判断地。',C('intelligently.s1','数据判断','Mira intelligently checked the source and date before sharing the chart with her colleagues.','米拉明智地先核对图表的来源和日期，然后才与同事分享。','Mira intelligently checked the source and date / before sharing the chart / with her colleagues.','intelligently 修饰 checked，表示她采用了明智的做法；before 表明核验在分享之前。','先检查来源能避免传播过时或不可靠信息，符合 s1。'),M('Mira acted intelligently by sharing an undated chart without checking who created it.','Mira acted carelessly by sharing an undated chart without checking its source.','不核验来源便分享信息不是明智判断。'),[Q('intelligently',1,1,'To act intelligently is to act?','with good judgment and understanding','without considering any evidence','in a way that inters a body','intelligently 表示明智地、有才智地。'),Q('intelligently',2,1,'Which choice is intelligent?','checking a chart’s source before sharing it','forwarding it without reading the date','assuming every claim is correct','核对来源体现良好判断。'),Q('intelligently',3,1,'Intelligently is an?','adverb','noun for a company paying claims','adjective meaning impossible to overcome','-ly 形式是副词。'),Q('intelligently',4,1,'A close synonym for intelligently is?','wisely','carelessly','intensely','wisely 强调良好判断。')]);
P('intensely','intensely 由 intense 加 -ly 构成，表示以很强的力量、深度或专注程度进行。',C('intensely.s1','艺术创作','The violinist listened intensely to the ensemble so she could enter at exactly the right moment.','小提琴手非常专注地聆听合奏，以便在恰当时机进入演奏。','The violinist listened intensely / to the ensemble / so she could enter / at exactly the right moment.','intensely 修饰 listened，强调专注程度；so 引出专注聆听的目的。','她高度集中注意力，符合 s1。'),M('The violinist listened intensely while paying no attention to the ensemble and missing every cue.','The violinist listened distractedly and missed the ensemble’s cues.','完全不注意并错过所有提示，不是 intensely 专注聆听。'),[Q('intensely',1,1,'Intensely means?','with great force, depth, or concentration','in brief separate intervals','by accident without a decision','intensely 表示强烈地或高度专注地。'),Q('intensely',2,1,'Listening intensely to music means?','concentrating deeply on it','hearing it only by chance','interrupting it repeatedly','高度专注地听符合该义。'),Q('intensely',3,1,'Which phrase is natural?','intensely interested','intensely between two cities','intensely a company that pays claims','intensely 可修饰 interested。'),Q('intensely',4,1,'The adjective related to intensely is?','intense','intelligent','interactive','intensely 由 intense 派生。')]);
P('intensively','intensively 由 intensive 加 -ly 构成，表示以集中投入或高强度的方式进行。',C('intensively.s1','技能训练','The apprentices trained intensively for two weeks, combining daily practice with detailed feedback from their instructor.','学徒们进行了为期两周的密集训练，把每日练习与导师的详细反馈结合起来。','The apprentices trained intensively / for two weeks / combining daily practice / with detailed feedback from their instructor.','intensively 修饰 trained，强调集中投入；combining 补充训练安排。','短期内每日练习并接受密集反馈，符合 s1。'),M('The course ran intensively with one brief session each year and no practice or feedback.','The course ran occasionally because it had only one brief session each year.','每年一次短课并非集中投入的训练。'),[Q('intensively',1,1,'To work intensively is to work?','with concentrated effort or a high level of input','with no effort at all','only at unpredictable intervals','intensively 指密集地、投入度高地。'),Q('intensively',2,1,'An intensive two-week course might include?','daily practice and frequent feedback','one short meeting each year','no lessons or exercises','高强度课程会集中安排练习。'),Q('intensively',3,1,'Which phrase is natural?','study intensively','study intercity','study intentionally by accident','intensively 可修饰 study。'),Q('intensively',4,1,'The adjective related to intensively is?','intensive','intense','intangible','intensively 由 intensive 派生。')]);
P('intentionally','intentionally 由 intentional 加副词后缀 -ly 构成，表示依据决定而故意地做某事。',C('intentionally.s1','实验记录','The technician intentionally changed one setting at a time so the team could identify which adjustment affected the result.','技术员故意一次只改变一个设置，以便团队确定是哪项调整影响了结果。','The technician intentionally changed one setting at a time / so the team could identify / which adjustment / affected the result.','intentionally 修饰 changed，表示有意为之；so 引出控制变量的实验目的。','一次只改一个参数是有计划的选择，符合 s1。'),M('The technician changed the setting intentionally by bumping the control accidentally without noticing.','The technician changed the setting accidentally when the control was bumped.','不小心碰到控制键不是故意调整。'),[Q('intentionally',1,1,'Intentionally means?','deliberately as a result of a decision','by accident with no decision','so slightly that it cannot be noticed','intentionally 表示故意地。'),Q('intentionally',2,1,'Why change one setting intentionally at a time?','to learn which adjustment affects the result','to make the data impossible to interpret','to avoid recording what changed','有计划地控制变量便于判断因果。'),Q('intentionally',3,1,'Which sentence uses intentionally correctly?','She intentionally left time for questions.','She intentionally forgot by accident.','She intentional answered with a question.','有意预留提问时间是 intentional。'),Q('intentionally',4,1,'The related adjective is?','intentional','intense','interdependent','intentionally 来自 intentional。')]);
P('intently','intently 由 intent（专注的）加 -ly 构成，表示目光或注意力完全集中在某一事物上。',C('intently.s1','课堂观察','The pupils listened intently as the scientist demonstrated how the small sensor detected movement.','科学家演示小型传感器如何检测移动时，学生们专心地听着。','The pupils listened intently / as the scientist demonstrated / how the small sensor / detected movement.','intently 修饰 listened，表示注意力集中；as 从句交代倾听的场景。','学生专心听讲，符合 s1。'),M('The pupils listened intently while talking loudly to one another and ignoring the demonstration.','The pupils listened inattentively because they talked and ignored the demonstration.','聊天且忽略演示说明没有专心听。'),[Q('intently',1,1,'To look intently at something is to look?','with the mind or eyes fully directed at it','without noticing it','with a sudden burst of anger','intently 表示专心地。'),Q('intently',2,1,'The pupils listened intently means they?','focused their attention on the demonstration','ignored it completely','interrupted the speaker repeatedly','专心倾听表示注意力集中。'),Q('intently',3,1,'Which phrase is natural?','watch intently','watch intently at between','watch an intently','intently 可修饰 watch。'),Q('intently',4,1,'A close synonym for intently is?','attentively','indifferently','intermittently','attentively 表示专注地。')]);
P('inter','inter 有两种不同词源：作动词时源自拉丁语 interrare，指埋葬；作前缀或拉丁语介词时 inter 表示“在……之间”。',C('inter.s1','纪念仪式','The family chose to inter the urn in the memorial garden beside the other family members.','家人选择把骨灰瓮安葬在纪念花园里，放在其他家人旁边。','The family chose to inter the urn / in the memorial garden / beside the other family members.','inter 作动词表示安葬；to inter 引出选择的行动，地点由 in 短语说明。','骨灰瓮被安放入墓地，符合 s1。'),M('The records said the family interred the urn by carrying it away from the cemetery and leaving it unburied.','The records said the family kept the urn unburied rather than interring it.','带离墓地且没有安葬不符合 inter 的动词义。'),[Q('inter',1,1,'To inter a body or urn is to?','place it in a grave or tomb','connect two computer systems','make an intercity journey','动词 inter 指安葬。'),Q('inter',2,2,'In a Latin phrase, inter can mean?','between','under the ground only','with great concentration','s2 指在……之间。'),Q('inter',3,1,'Which sentence uses inter as a verb?','They interred the urn in the family plot.','The road runs between the cities.','The intercity train arrived.','interred 作“安葬”解。'),Q('inter',4,1,'The English verb inter is unrelated in sense to the prefix inter- meaning?','between','bury','place in a tomb','同形词源不同，前缀 inter- 表示“在……之间”。')]);
P('interaction','interaction 由 inter-（相互）与 action 构成，指两个或多个参与者彼此作用的方式。',C('interaction.s1','用户测试','The researchers observed the interaction between visitors and the touchscreen display during the museum trial.','研究人员在博物馆试用期间观察了访客与触屏显示器之间的互动。','The researchers observed the interaction / between visitors and the touchscreen display / during the museum trial.','interaction between A and B 表示双方相互作用；during 引出观察发生的时间。','访客与屏幕互相影响，符合 s1。'),M('The report called the silent, disconnected visitors and screen an interaction even though neither affected the other.','The report called their use separate rather than an interaction because neither affected the other.','双方互不作用时不能称为 interaction。'),[Q('interaction',1,1,'Interaction is?','the way two or more people or things act on each other','one isolated thing acting with no response','a person’s private intention','interaction 指相互作用。'),Q('interaction',2,1,'A visitor uses a touchscreen and receives feedback; this is?','an interaction','an interment','an insurgence','双方操作与反馈构成互动。'),Q('interaction',3,1,'Which phrase is natural?','interaction between the teams','interaction among to the teams','interaction by a team between','常见结构 interaction between。'),Q('interaction',4,1,'Interaction is related to?','interact','inter','intercity','interact 表示相互作用。')]);
P('interactive','interactive 由 interact 加 -ive 构成，形容包含双向交流或相互影响的。',C('interactive.s1','数字展览','The museum built an interactive map that lets visitors select a region and hear local residents describe it.','博物馆制作了一幅互动地图，访客可以选择地区并收听当地居民的介绍。','The museum built an interactive map / that lets visitors select a region / and hear local residents / describe it.','interactive 修饰 map，表示用户的选择会触发回应；that 从句说明双向互动方式。','访客选择与地图回应构成双向交流，符合 s1。'),M('The exhibit was interactive even though visitors could neither select anything nor receive a response from it.','The exhibit was static because visitors could not interact with it.','无法操作也无任何回应不符合 interactive。'),[Q('interactive',1,1,'An interactive exhibit involves?','communication or influence in both directions','a one-way display with no response','a private investigation','interactive 指互动的。'),Q('interactive',2,1,'On an interactive map, visitors may?','select a region and receive information','look at a fixed picture only','inter a memorial urn','用户选择触发回应体现互动。'),Q('interactive',3,1,'Which classroom tool is interactive?','a quiz that responds to students’ answers','a poster that never changes','a closed book on a shelf','根据回答作出反馈的是互动工具。'),Q('interactive',4,1,'Interactive is related to the verb?','interact','interbreed','insure','interactive 由 interact 派生。')]);
P('interbedded','interbedded 由 inter- 与 bed（岩层）构成，地质学中形容一层夹在其他岩层之间或与其交替出现。',C('interbedded.s1','地质剖面','The geologist found thin volcanic ash layers interbedded with sandstone in the cliff face.','地质学家在崖壁剖面中发现薄火山灰层与砂岩互层。','The geologist found thin volcanic ash layers / interbedded with sandstone / in the cliff face.','interbedded 修饰 ash layers，常用 interbedded with 表示与另一岩层交错夹置。','火山灰层夹在砂岩层间，符合 s1。'),M('The ash layer was called interbedded with sandstone even though it lay entirely above the sandstone with no alternating layers.','The ash layer lay above the sandstone and was not interbedded with it.','互不夹置、完全分层不符合互层关系。'),[Q('interbedded',1,1,'Interbedded rock layers occur?','between or alternating with other beds','only above all other layers','without any relation to neighboring beds','interbedded 指呈互层的。'),Q('interbedded',2,1,'Ash layers interbedded with sandstone are?','mixed between sandstone beds','located far above an unrelated formation','made of a single unbroken mineral','互层表示不同层交替或夹置。'),Q('interbedded',3,1,'Which phrase is natural?','interbedded with limestone','interbedded from limestone only','interbedded to above limestone','常用搭配 interbedded with。'),Q('interbedded',4,1,'The term interbedded is most likely used in?','geology','insurance claims','voice training','interbedded 描述地质岩层。')]);
P('interbreed','interbreed 可指动物或植物跨品种、物种繁殖，也可作及物动词表示使不同品种或物种杂交。',C('interbreed.s1','植物育种','The two compatible plant varieties can interbreed and produce offspring with traits from both lines.','这两个相容的植物品种可以杂交，产生同时具有两条品系特征的后代。','The two compatible plant varieties can interbreed / and produce offspring / with traits / from both lines.','interbreed 在此不及物，指两个品种共同繁殖；and 连接繁殖与后代结果。','不同品种产生混合特征后代，符合 s1。'),M('The two varieties interbred but produced no offspring and had no reproductive interaction at all.','The two varieties did not interbreed because they produced no offspring.','没有共同繁殖或后代，不能称为 interbreed。'),[Q('interbreed',1,1,'When animals or plants interbreed, they?','produce offspring across breed or species lines','are simply placed in the same room','cannot reproduce at all','s1 指不同品种或物种间繁殖。'),Q('interbreed',2,2,'To interbreed two varieties is to?','cause them to breed together','prevent them from reproducing','intercede between their owners','s2 是使杂交。'),Q('interbreed',3,1,'Which example fits interbreed?','two compatible plant lines produce mixed-trait offspring','two plants are stored in separate boxes','a plant is measured without breeding','共同繁殖产生后代符合该义。'),Q('interbreed',4,1,'The prefix inter- in interbreed suggests?','between or with one another','not at all','inside a tomb','此处表示不同品系之间繁殖。')]);
P('intercede','intercede 源自拉丁语 intercedere（走到中间），指代表他人介入，试图结束争吵或减轻惩罚。',C('intercede.s1','校园调解','A counselor interceded for the students by asking the dean to hear both sides before deciding on a suspension.','辅导员替学生出面说情，请院长在决定停学处分前先听取双方意见。','A counselor interceded for the students / by asking the dean to hear both sides / before deciding / on a suspension.','intercede for someone 表示替某人说情；by 引出介入的方式。','辅导员代表学生请求公平听取，符合 s1。'),M('The counselor interceded for the students by refusing to speak for them or contact the dean.','The counselor stayed out of the matter instead of interceding for the students.','拒绝介入、拒绝代为沟通不符合 intercede。'),[Q('intercede',1,1,'To intercede for someone is to?','intervene on their behalf','formally accuse them','make them interbreed','intercede 指替人说情或调解。'),Q('intercede',2,1,'A counselor interceded by?','asking the dean to hear both sides','ignoring the dispute entirely','issuing the final suspension alone','介入并请求公平听取双方意见。'),Q('intercede',3,1,'Which phrase is natural?','intercede for a colleague','intercede a colleague into a room','intercede at a conflict with no one','常见结构 intercede for someone。'),Q('intercede',4,1,'The aim of interceding may be to?','end a quarrel or lessen a punishment','increase conflict','impose an unrelated tax','词条指出介入旨在缓解争执或惩罚。')]);
P('interchangeable','interchangeable 由 inter-、change 与 -able 构成，形容两个事物能彼此替换且结果不变的。',C('interchangeable.s1','设备配件','The two adapter tips are interchangeable, so either one fits the device without changing how it works.','这两个转接头可以互换，任意一个装上设备都不会改变其工作方式。','The two adapter tips are interchangeable / so either one fits the device / without changing / how it works.','interchangeable 表示可以互换；so 说明替换后功能不变。','两配件可相互替代且效果相同，符合 s1。'),M('The adapters were interchangeable even though one did not fit the device and changed how it operated.','The adapters were not interchangeable because one did not fit the device.','不能安装且改变工作结果的配件不能互换。'),[Q('interchangeable',1,1,'Two parts are interchangeable if?','they can replace each other without changing the result','they look alike but cannot be used','they are interred in the same place','interchangeable 指可互换的。'),Q('interchangeable',2,1,'If either adapter works the same way, the tips are?','interchangeable','interbedded','insurmountable','替换后功能不变符合该义。'),Q('interchangeable',3,1,'Which phrase is natural?','the terms are not interchangeable','the terms are interchanged with no result','the terms can interchangeable','interchangeable 可作表语形容词。'),Q('interchangeable',4,1,'A close opposite of interchangeable is?','not substitutable','replaceable','compatible','不能互换与 interchangeable 相反。')]);
P('intercity','intercity 由 inter-（之间）与 city 构成，形容连接不同城市之间的交通或服务。',C('intercity.s1','铁路出行','The intercity train connects the capital with three coastal towns and stops only at major stations.','这趟城际列车连接首都和三个沿海城镇，只停靠主要车站。','The intercity train connects the capital / with three coastal towns / and stops only / at major stations.','intercity 修饰 train，表示城市之间运行；with 引出连接的地点。','列车连接多个城市，符合 s1。'),M('The service was called intercity even though it ran only within a single neighborhood and never reached another city.','The service was called local because it stayed within one neighborhood.','只在单一社区运行的服务不是城际交通。'),[Q('intercity',1,1,'An intercity train travels?','between cities','only within one building','between stars','intercity 指城市之间的。'),Q('intercity',2,1,'An intercity bus route may connect?','a capital and nearby towns','two rooms in one house','two planets beyond the solar system','城际交通连接不同城市。'),Q('intercity',3,1,'The prefix inter- in intercity means?','between','inside','not','inter- 表示在……之间。'),Q('intercity',4,1,'Which phrase is natural?','intercity rail service','intercity within a single room','intercity to across one seat','城际铁路连接城市。')]);
P('intercommunity','intercommunity combines inter- “between” with community; it describes relations or activity linking separate communities.',C('intercommunity.s1','跨社区公共服务','The intercommunity council brought residents from four towns together to coordinate a shared emergency shelter.','跨社区理事会召集四个城镇的居民，共同协调一处应急避难所。','The intercommunity council / brought residents from four towns together / to coordinate / a shared emergency shelter.','intercommunity 修饰 council，强调跨越不同社区；to coordinate 表示召集居民的目的。','四个城镇共同协调公共资源，符合 s1 的跨社区关系。'),M('The council was intercommunity although it represented one household and dealt with no other community.','The council was neighborhood-based because it represented only one household.','只有一个家庭参与不构成社区之间的联系。'),[Q('intercommunity',1,1,'An intercommunity project links?','people or institutions from different communities','departments within one person','objects buried in one grave','intercommunity 表示社区之间的。'),Q('intercommunity',2,2,'Which plan best fits intercommunity contact?','neighboring towns coordinating a shared clinic','one town repainting its own office','a single resident updating a diary','跨社区联系涉及不同社区共同协作。'),Q('intercommunity',3,1,'The council is intercommunity because it?','coordinates residents of several towns','serves one isolated household','operates only inside one classroom','多个城镇参与，符合跨社区。'),Q('intercommunity',4,2,'Intercommunity can describe?','a link or exchange between communities','a private thought within one person','a device measuring wavelengths','该词可表示社区间联系或互动。')]);
P('interconnect','interconnect combines inter- “with one another” and connect: things may be linked, or someone may link them.',C('interconnect.s1','供水网络','The reservoirs interconnect through underground pipes, allowing water to be redirected when one section needs maintenance.','这些蓄水池通过地下管道相互连接，因此某一段需要维护时可以改道输水。','The reservoirs interconnect / through underground pipes / allowing water to be redirected / when one section needs maintenance.','interconnect 在此是不及物用法，主语 reservoirs 彼此连通；allowing 补充连接带来的功能。','蓄水池通过管道连成网络，符合 s1。'),M('The reservoirs interconnect even though each is sealed off and no pipe or channel joins any pair.','The reservoirs remain separate because no pipe joins them.','没有通道相连就不能说蓄水池彼此 interconnect。'),[Q('interconnect',1,1,'If systems interconnect, they?','are linked with one another','are deliberately kept isolated','are questioned in court','interconnect 表示相互连接。'),Q('interconnect',2,2,'The reservoirs interconnect through?','pipes that let water pass between them','separate sealed walls','a list of unrelated names','管道构成连接并允许输水。'),Q('interconnect',3,1,'Which sentence uses interconnect naturally?','The regional rail lines interconnect at the central station.','The regional rail interconnects between because station.','The rail lines are interconnect yesterday.','线路可在车站相互连接。'),Q('interconnect',4,2,'Interconnect may be used transitively to mean?','join separate things together','make a question sound doubtful','separate things permanently','及物用法表示把事物连接起来。')]);
P('interdependence','interdependence is formed from interdependent plus -ence and names the condition in which each side relies on another.',C('interdependence.s1','生态系统','The interdependence of bees and flowering plants became clear when fewer pollinators led to smaller seed harvests.','传粉者减少导致种子收成下降，这清楚地体现了蜜蜂与开花植物之间的相互依存。','The interdependence of bees and flowering plants / became clear / when fewer pollinators led / to smaller seed harvests.','interdependence 是主语中心词；when 引出一种生物减少对另一方造成的结果。','两方各自的繁衍与生存互相影响，符合 s1。'),M('The report described interdependence although each species survived unchanged with no effect on the other.','The report described independence because neither species affected the other.','彼此毫无影响体现独立而非相互依存。'),[Q('interdependence',1,1,'Interdependence is a relationship in which?','each side depends on the other','one side is entirely unrelated to the other','both sides are permanently separated','interdependence 指相互依存。'),Q('interdependence',2,1,'A fall in bees reducing seed production shows?','interdependence between pollinators and plants','that the species have no connection','that plants are made of metal','一方减少影响另一方，体现相互依存。'),Q('interdependence',3,1,'Which phrase is natural?','the economic interdependence of two regions','the interdependence of a sealed box with no links','an interdependence person who works alone','interdependence 可描述地区间经济依存。'),Q('interdependence',4,1,'A close opposite of interdependence is?','independence','mutual reliance','reciprocal need','independence 表示相互不依赖。')]);
P('interdependent','interdependent combines inter- and dependent; it describes people, parts, or systems that rely on one another.',C('interdependent.s1','城市基础设施','A city’s transport and power systems are interdependent: a prolonged blackout can stop trains, while stalled trains complicate repairs.','城市的交通与电力系统相互依存：长期停电会使列车停运，而列车停运又会增加维修难度。','A city’s transport and power systems are interdependent / a prolonged blackout can stop trains / while stalled trains / complicate repairs.','interdependent 作表语说明两套系统的关系；冒号后的例子显示双向影响。','电力和交通彼此影响、相互依赖，符合 s1。'),M('The systems were interdependent even though changes in either system could never affect the other.','The systems were independent because neither affected the other.','双方互不影响就不构成 interdependent。'),[Q('interdependent',1,1,'Interdependent systems?','depend on one another','operate with no possible connection','are located between galaxies','interdependent 表示相互依赖的。'),Q('interdependent',2,1,'Why are transport and power called interdependent here?','a problem in either can affect the other','they are both painted the same color','they were built on different continents','题句说明两系统的故障互相影响。'),Q('interdependent',3,1,'Which sentence is correct?','The departments are interdependent and share key data.','The departments interdependently the data yesterday.','The department is interdependence of data.','interdependent 可作表语形容词。'),Q('interdependent',4,1,'Which noun names the state of being interdependent?','interdependence','interruption','intertidal','interdependence 是相互依存状态。')]);
P('interdisciplinary','interdisciplinary combines inter- with disciplinary, describing work that draws on more than one academic field.',C('interdisciplinary.s1','大学研究','The interdisciplinary team paired a historian with climate scientists to study how drought changed settlement patterns.','这个跨学科团队让历史学家与气候科学家合作，研究干旱如何改变聚居模式。','The interdisciplinary team / paired a historian with climate scientists / to study / how drought changed settlement patterns.','interdisciplinary 修饰 team；配对不同学科研究者说明研究结合多个领域。','历史与气候科学共同回答问题，符合 s1。'),M('The project was interdisciplinary although it used one narrow field and excluded every other discipline.','The project was single-discipline because it excluded all other fields.','仅限一个领域的项目不能称作 interdisciplinary。'),[Q('interdisciplinary',1,1,'interdisciplinary research draws on?','more than one field of study','only one field and no related methods','no academic field at all','interdisciplinary 指跨学科的。'),Q('interdisciplinary',2,1,'Which team is interdisciplinary?','historians and climate scientists studying drought','only historians cataloguing one archive','a group with no research question','两个学科合作构成跨学科团队。'),Q('interdisciplinary',3,1,'Which phrase is natural?','an interdisciplinary course in art and engineering','an interdisciplinary course with no subject','an interdisciplinary between one person','该形容词可修饰融合领域的课程。'),Q('interdisciplinary',4,1,'The prefix inter- here suggests?','between or across disciplines','inside one discipline only','opposed to all disciplines','inter- 表示学科之间。')]);
P('interesting','interesting means arousing curiosity or attention; its subject is the thing that makes people interested.',C('interesting.s1','博物馆讲解','The curator found an interesting letter behind the portrait because it revealed who had commissioned the painting.','馆长在肖像画后发现一封有趣的信，因为它揭示了是谁委托创作这幅画。','The curator found an interesting letter / behind the portrait / because it revealed / who had commissioned the painting.','interesting 修饰 letter，表示信引起兴趣；because 引出其吸引人的原因。','信揭示新的历史信息，能够引起好奇，符合 s1。'),M('The letter was interesting because nobody noticed it, nobody read it, and it revealed nothing to anyone.','The letter was unremarkable because it attracted no attention and revealed nothing.','既无信息也不引起注意的信不具备 interesting 的特点。'),[Q('interesting',1,1,'An interesting story is one that?','arouses curiosity or attention','cannot be noticed by anyone','is necessarily false','interesting 表示引起兴趣的。'),Q('interesting',2,1,'Why was the letter interesting to the curator?','it revealed who ordered the portrait','it was blank and gave no clue','it had already been discarded','信提供了新的历史线索。'),Q('interesting',3,1,'Which phrase is grammatical?','an interesting question','an interested question that attracts nobody','an interestingly question','interesting 可作形容词修饰 question。'),Q('interesting',4,1,'If a subject is interesting, people are often?','interested in it','interred in it','interlocked in it','事物 interesting，人对它 interested。')]);
P('interestingly','interestingly is the adverb formed from interesting; it often introduces a fact the speaker considers noteworthy or curious.',C('interestingly.s1','田野调查','Interestingly, the oldest trees in the valley grew on the rocky slope, where the soil was thinnest.','有意思的是，山谷里最古老的树长在土层最薄的岩坡上。','Interestingly / the oldest trees in the valley / grew on the rocky slope / where the soil was thinnest.','句首 Interestingly 评述整个事实，提示后文结果值得注意；where 引出地点特征。','树龄最大与土层最薄这一反差构成值得注意的事实，符合 s1。'),M('Interestingly, the report contained no surprising or noteworthy fact and merely repeated a common date.','The report simply stated a familiar date without any noteworthy detail.','句子没有新奇或值得关注的信息，不适合用 Interestingly 引出。'),[Q('interestingly',1,1,'Sentence-initial Interestingly usually signals?','a fact the speaker finds noteworthy','a command to stop speaking','a measurement of temperature','它常提示一个值得注意的事实。'),Q('interestingly',2,1,'Why is the tree finding interesting here?','the oldest trees grew where soil was thinnest','all trees had the same age and soil','no trees were found in the valley','结果与通常预期形成反差。'),Q('interestingly',3,1,'Which punctuation is natural?','Interestingly, the map omits the old road.','Interesting, the map omits old roadly.','Interestingly the, map omits road.','句首副词后通常加逗号。'),Q('interestingly',4,1,'Interestingly is derived from which adjective?','interesting','intertidal','interdependent','interestingly 由 interesting 加 -ly 构成。')]);
P('interferometer','interferometer is built from interfere/interference and -meter, a device that measures through the interaction of waves.',C('interferometer.s1','天文仪器','Astronomers linked two telescopes as an interferometer to detect tiny changes in the size of a distant star.','天文学家把两台望远镜连接成干涉仪，以探测遥远恒星大小的微小变化。','Astronomers linked two telescopes / as an interferometer / to detect tiny changes / in the size of a distant star.','interferometer 是仪器名称；to detect 说明其测量用途。','仪器借助波的干涉检测极微小差异，符合 s1。'),M('The interferometer measured the star by blocking every wave and comparing no signals.','The instrument could not act as an interferometer because it blocked all signals.','干涉仪依靠波信号的相互作用测量；阻断信号无法实现该功能。'),[Q('interferometer',1,1,'An interferometer is an instrument that measures using?','the interaction or interference of waves','the weight of a person’s handwriting','the color of an unrelated flag','干涉仪利用波的干涉进行测量。'),Q('interferometer',2,1,'Astronomers used the device to detect?','tiny changes in a distant star','the taste of the telescope lens','a town’s legal boundaries','它能测量很小的距离或尺寸变化。'),Q('interferometer',3,1,'Which instrument name is correctly spelled?','interferometer','interferomenter','interfermeter','正确词形是 interferometer。'),Q('interferometer',4,1,'The suffix -meter suggests an instrument for?','measuring','greeting','breeding','-meter 常见于测量仪器名称。')]);
P('intergalactic','intergalactic combines inter- “between” and galactic, referring to space between galaxies.',C('intergalactic.s1','天文学科普','The probe would need extraordinary travel time to cross the intergalactic space separating the Milky Way from its nearest large neighbor.','探测器要穿越银河系与最近的大型邻居星系之间的星系际空间，需要极长时间。','The probe would need extraordinary travel time / to cross the intergalactic space / separating the Milky Way / from its nearest large neighbor.','intergalactic 修饰 space；分词 separating 说明这片空间的位置。','空间位于两个星系之间，符合 s1。'),M('The region was intergalactic even though it lay entirely inside one star and between no galaxies.','The region was interstellar because it lay among stars within one galaxy.','星际空间是恒星之间；intergalactic 特指星系之间。'),[Q('intergalactic',1,1,'Intergalactic space lies?','between galaxies','inside the core of one atom','only between two city blocks','intergalactic 指星系之间的。'),Q('intergalactic',2,1,'Which is an intergalactic distance?','the gap between the Milky Way and another galaxy','the distance between two rooms','the gap between two pages','题目所述是星系之间的尺度。'),Q('intergalactic',3,1,'The prefix inter- in intergalactic means?','between','below','without','inter- 表示在……之间。'),Q('intergalactic',4,1,'Intergalactic differs from interstellar because it concerns?','space between galaxies rather than among stars','one person’s private thoughts','a period between ice ages','二者分别涉及星系间和恒星间空间。')]);
P('interglacial','interglacial combines inter- “between” and glacial, naming a relatively warm interval between ice ages or glacial periods.',C('interglacial.s1','古气候研究','During the last interglacial, warmer conditions allowed forests to spread across areas that are tundra today.','在上一个间冰期，较温暖的气候使森林扩展到如今属于苔原的地区。','During the last interglacial / warmer conditions allowed forests to spread / across areas / that are tundra today.','interglacial 在此作名词，指一个时期；that 从句限定这些地区。','间冰期位于冰期之间且气候相对温暖，符合 s1。'),M('Researchers called it an interglacial although it was the coldest part of an ongoing glacial period.','Researchers called it a glacial maximum because it was the coldest part of an ice age.','冰期中最冷阶段不是冰期之间的暖期。'),[Q('interglacial',1,1,'An interglacial is a relatively warm period?','between glacial periods','at the center of a single snowflake','after every summer day','interglacial 指冰期之间的暖期。'),Q('interglacial',2,1,'What might happen during an interglacial?','forests expand into formerly colder areas','all ice ages become warmer in one afternoon','galaxies collide with no climate change','气候变暖可让森林向寒冷地区扩展。'),Q('interglacial',3,1,'Which phrase is natural?','the last interglacial period','the interglacial between two bus stops','an interglacially glacier','常见表达为 interglacial period。'),Q('interglacial',4,1,'The prefix inter- suggests this period occurs?','between ice ages or glacial stages','inside one glacier crystal','without any climate variation','inter- 表示两个冰期阶段之间。')]);
P('interject','interject comes from Latin intericere, “throw between”; to interject is to insert a remark abruptly into a conversation.',C('interject.s1','会议讨论','“Could we check the figures first?” Maya interjected as the committee moved toward a decision.','委员会正准备作出决定时，玛雅插话说：“我们能先核对一下数据吗？”','“Could we check the figures first?” / Maya interjected / as the committee moved / toward a decision.','interjected 表示在他人讨论中突然插话；as 从句交代发生时机。','玛雅突然加入一句话，打断了讨论进程，符合 s1。'),M('Maya interjected by remaining silent throughout the meeting and making no remark.','Maya stayed silent and did not interject during the meeting.','保持沉默、不插话与 interject 的含义相反。'),[Q('interject',1,1,'To interject in a discussion is to?','insert a remark abruptly','listen without speaking','end a conversation by leaving silently','interject 指插话。'),Q('interject',2,1,'Maya interjected when she?','added a question while the committee was speaking','left before the meeting began','wrote a report a month later','她在讨论过程中加入话语。'),Q('interject',3,1,'Which sentence is natural?','“Wait,” he interjected.','“Wait,” he interjectly.','He interjected the room silently.','interject 可用引语表示插话内容。'),Q('interject',4,1,'Interject is closest in meaning to?','interrupt with a comment','interdepend on a system','interlock two gears','interject 是以评论插入或打断。')]);
P('interlock','interlock can mean that parts fit together so they cannot move freely, or that a mechanism links them in this way.',C('interlock.s1','安全扣具','The metal teeth interlock when the buckle closes, preventing the two straps from slipping apart.','扣具合上时金属齿彼此咬合，防止两条带子滑开。','The metal teeth interlock / when the buckle closes / preventing the two straps / from slipping apart.','interlock 在此是不及物用法，teeth 彼此咬合；preventing 表示其结果。','齿轮状部件扣合并限制滑脱，符合 s1。'),M('The teeth interlocked even though they remained far apart and never touched or fitted together.','The teeth did not interlock because they never met or fitted together.','部件既不接触也不嵌合，不能说 interlock。'),[Q('interlock',1,1,'When parts interlock, they?','fit together and constrain one another','remain separated with no contact','are questioned one after another','interlock 表示彼此咬合。'),Q('interlock',2,1,'What happens when the buckle teeth interlock?','the straps are less likely to slip apart','the buckle turns into a telescope','the straps become unrelated to the buckle','咬合固定带子，防止滑脱。'),Q('interlock',3,1,'Which use is grammatical?','The gears interlock.','The gears interlockly.','The gears are interlock yesterday.','interlock 可作动词。'),Q('interlock',4,2,'Interlock can also mean to?','connect parts through a locking mechanism','ask a witness formal questions','describe space among stars','及物用法可表示使部件联锁。')]);
P('interlocking','interlocking is the -ing form/adjective of interlock and describes parts joined so that they fit or constrain one another.',C('interlocking.s1','拼接砖块','The path was built from interlocking pavers whose shaped edges kept neighboring stones from shifting.','这条小路由互锁铺路砖铺成，砖块的异形边缘防止相邻石块移位。','The path was built from interlocking pavers / whose shaped edges / kept neighboring stones / from shifting.','interlocking 修饰 pavers，说明砖块边缘彼此嵌合；whose 指 pavers。','形状相配的砖相互咬合并防止移位，符合 s1。'),M('The pavers were interlocking even though smooth gaps separated them and their edges could not fit.','The pavers were loose because their edges did not fit together.','边缘不嵌合的砖不会互锁。'),[Q('interlocking',1,1,'Interlocking blocks are blocks that?','fit together so they hold one another in place','float separately with no contact','cannot be used to build anything','interlocking 描述互相咬合的部件。'),Q('interlocking',2,1,'Why did the shaped pavers stay in place?','their edges interlocked with neighboring stones','they were not laid on the path','they were made of liquid','异形边缘相互嵌合，减少移位。'),Q('interlocking',3,1,'Which phrase is natural?','interlocking parts of a mechanism','interlocking apart from each other','the parts interlockingly yesterday','interlocking 可作定语修饰 parts。'),Q('interlocking',4,1,'Interlocking is related to which verb?','interlock','interject','interrogate','interlocking 是 interlock 的形式。')]);
P('interlude','interlude comes through Medieval Latin interludium, a “play between”; it now often means a short interval or episode between larger events.',C('interlude.s1','音乐会节目','A brief piano solo served as an interlude between the two longer orchestral works.','一段简短的钢琴独奏作为两首较长管弦乐曲之间的插曲。','A brief piano solo / served as an interlude / between the two longer / orchestral works.','interlude 作表语名词；between 指它位于两首较长作品之间。','短曲穿插在两个较长节目之间，符合 s1。'),M('The solo was an interlude between the works although it lasted for the entire concert and no other work followed.','The solo was the main work of the concert, not a brief interval between pieces.','贯穿整场且没有前后作品的节目不构成两作品间的插曲。'),[Q('interlude',1,1,'An interlude is often?','a short interval or episode between larger parts','the permanent end of every event','a person who translates speech','interlude 常指较大部分之间的短暂插曲。'),Q('interlude',2,1,'Why was the piano solo an interlude?','it came between two longer works','it replaced the entire concert','it was played before any event was planned','它位于两首较长作品之间。'),Q('interlude',3,1,'Which phrase is natural?','a comic interlude during the ceremony','an interlude that is the only event ever','interlude between two unrelated galaxies','interlude 可指活动中的短插曲。'),Q('interlude',4,1,'The word historically contains a sense of?','a play or event in between','a tool for measuring waves','a formal accusation','词源成分带有“中间的一场表演”之意。')]);
P('intermediary','intermediary derives from intermediate and names a person or thing that stands between parties, stages, or processes.',C('intermediary.s1','商业谈判','A local intermediary introduced the two companies and helped them agree on terms for the joint venture.','一位当地中间人牵线搭桥，帮助两家公司就合资项目的条件达成一致。','A local intermediary / introduced the two companies / and helped them agree / on terms for the joint venture.','intermediary 作名词，指双方之间的中间人；introduced 和 helped 描述其作用。','此人沟通双方并促成协议，符合 s1。'),M('The intermediary helped the companies negotiate while refusing to contact either company or pass messages between them.','The intermediary had no role because the companies negotiated directly.','不联系双方且不传递信息的人没有充当中间人。'),[Q('intermediary',1,1,'An intermediary may?','carry messages or arrange contact between parties','act as neither a person nor a link','measure the distance between galaxies','intermediary 可指双方间的中间人。'),Q('intermediary',2,1,'The local intermediary helped by?','introducing the companies and assisting talks','preventing the companies from meeting','replacing every employee at both firms','牵线并协助谈判体现中间人作用。'),Q('intermediary',3,1,'Which phrase is natural?','an intermediary between the buyer and seller','an intermediary inside one sealed box only','intermediary to the company yesterday','常用结构 intermediary between parties。'),Q('intermediary',4,2,'Intermediary may also describe something?','coming between stages or groups','that is always final and last','that has no relation to a process','它也可描述介于阶段或群体之间的事物。')]);
P('interminable','interminable comes from Latin interminabilis, “without end”; it describes something that seems to go on too long.',C('interminable.s1','旅途感受','After the train stopped in the tunnel, the passengers endured an interminable hour with no announcement.','列车在隧道里停下后，乘客在没有任何广播的情况下熬过了漫长得仿佛没有尽头的一小时。','After the train stopped in the tunnel / the passengers endured / an interminable hour / with no announcement.','interminable 修饰 hour，表达主观上漫长难熬；after 引出事件背景。','等待仅一小时却显得没有尽头，符合 s1 的语感。'),M('The break was interminable even though it lasted only one second and everyone felt it passed instantly.','The break was brief because it lasted only a second and passed instantly.','极短且转瞬即逝的间隔不应称为 interminable。'),[Q('interminable',1,1,'An interminable wait seems?','to continue for far too long','to end immediately','to happen between two galaxies','interminable 表示漫长得仿佛无尽。'),Q('interminable',2,1,'Why did the passengers call the hour interminable?','the delay felt endless and no announcement came','the train arrived immediately','they were told the precise end time at once','漫长且没有消息使等待难熬。'),Q('interminable',3,1,'Which phrase is natural?','an interminable meeting','an interminable one-second blink that felt instant','an interminably meeting','interminable 是形容词，可修饰 meeting。'),Q('interminable',4,1,'A close synonym is?','endless-seeming','momentary','interchangeable','近义表达是仿佛无尽的。')]);
P('intermittently','intermittently comes from intermittent plus -ly and means stopping and starting at intervals rather than continuing steadily.',C('intermittently.s1','设备故障','The warning light flashed intermittently throughout the night, so the mechanic checked for a loose connection.','整夜里警示灯断断续续地闪烁，因此机械师检查是否有接触松动。','The warning light flashed intermittently / throughout the night / so the mechanic checked / for a loose connection.','intermittently 修饰 flashed，说明闪烁并非连续；so 引出检查的原因。','灯光间歇出现，符合 s1。'),M('The warning light flashed intermittently in one unbroken beam that never stopped once.','The warning light glowed continuously without any breaks.','一次不间断的常亮是持续发生，不是间歇发生。'),[Q('intermittently',1,1,'If a light flashes intermittently, it flashes?','with pauses, stopping and starting','continuously without any break','only between two galaxies','intermittently 表示断断续续地。'),Q('intermittently',2,1,'Why might a mechanic inspect an intermittent warning light?','a loose connection may make it come and go','the light never turned on','the car had no electrical system','间歇亮灯可能源自连接不稳。'),Q('intermittently',3,1,'Which phrase is natural?','rain fell intermittently during the afternoon','rain fell intermittently without ever stopping','an intermittently rain','副词可修饰 fell，说明降雨时断时续。'),Q('intermittently',4,1,'The related adjective is?','intermittent','intermediate','intergalactic','intermittently 由 intermittent 派生。')]);
P('intermix','intermix means either to become mixed with other things or to mix things together.',C('intermix.s1','烘焙操作','Fold the berries gently into the batter until they intermix, but stop before the fruit is crushed.','将浆果轻轻拌入面糊，直到它们混合均匀；注意在水果被压碎前停下。','Fold the berries gently into the batter / until they intermix / but stop / before the fruit is crushed.','intermix 在此是不及物用法，berries 与 batter 混合；until 表示达到的状态。','浆果与面糊逐渐混合但保持完整，符合 s1。'),M('The ingredients intermixed even though they stayed in sealed separate bowls and never touched.','The ingredients remained separate because they never came into contact.','互不接触的食材不会 intermix。'),[Q('intermix',1,1,'When substances intermix, they?','become mixed together','remain sealed in separate containers','are formally questioned','intermix 可表示彼此混合。'),Q('intermix',2,2,'To intermix paint colors is to?','combine them together','keep each color in a separate sealed jar','measure their temperature only','及物用法是把颜色混合。'),Q('intermix',3,1,'Which sentence uses intermix naturally?','The scents intermixed in the warm room.','The scents intermixly on a table.','The scents were intermix by tomorrow.','气味可彼此混合，使用不及物动词。'),Q('intermix',4,2,'Intermix can be used?','with or without a direct object','only as a noun','only to mean “interrupt a speaker”','intermix 既可及物也可不及物。')]);
P('intermodal','intermodal combines inter- and modal, describing transport or systems that transfer between different modes.',C('intermodal.s1','货物运输','The intermodal shipment moved in one container from ship to rail and then to a truck for final delivery.','这批多式联运货物装在同一个集装箱中，从船转到铁路，再由卡车完成末端配送。','The intermodal shipment moved in one container / from ship to rail / and then to a truck / for final delivery.','intermodal 修饰 shipment，强调船、铁路和公路等运输方式之间的转换。','货物在不同运输模式之间转运，符合 s1。'),M('The shipment was intermodal although it traveled only by one truck and was never transferred to another mode.','The shipment was road-only because it used one truck and no other transport mode.','没有模式转换就不体现多式联运。'),[Q('intermodal',1,1,'Intermodal transport involves?','transfers between different transport modes','only one fixed mode with no transfer','travel only between galaxies','intermodal 指不同运输方式之间的。'),Q('intermodal',2,1,'Which shipment is intermodal?','a container moving by ship, rail, and truck','a parcel carried only by one bicycle','a passenger walking inside one room','货物在船、铁路、公路间转换。'),Q('intermodal',3,1,'The word modal here refers to a?','mode or method of transport','person who asks questions','geological ice age','modal 指方式或模式。'),Q('intermodal',4,1,'Which phrase is natural?','an intermodal freight terminal','an intermodal single-mode trip with no transfer','intermodal to between a ship','多式联运货运站是自然搭配。')]);
P('intern','intern can mean a student or graduate doing temporary supervised work for experience; it can also be a verb meaning to confine someone, especially in wartime.',C('intern.s1','新闻编辑部','This summer, the journalism intern checked quotations and learned how the newsroom verified breaking stories.','这名新闻专业实习生今年夏天核对引语，并学习新闻编辑部如何核实突发报道。','This summer / the journalism intern checked quotations / and learned / how the newsroom verified breaking stories.','intern 作名词，指短期获得工作经验的人；and 连接其工作与学习内容。','学生在监督下工作并积累经验，符合 s1。'),M('The newsroom intern gained experience by avoiding every assignment and refusing all supervision.','The newsroom trainee learned through supervised tasks and practical experience.','拒绝任务与指导不符合实习生积累经验的语境。'),[Q('intern',1,1,'A hospital or newsroom intern is usually?','a trainee doing temporary supervised work','a permanent building inspector only','a person measuring waves','intern 可指实习生。'),Q('intern',2,2,'In a historical context, to intern civilians may mean to?','confine them, especially during wartime','hire them for a summer placement','ask them to translate a speech','动词 intern 另有拘禁之义。'),Q('intern',3,1,'Which sentence uses intern as a noun?','The intern shadowed an editor for a month.','The government interned the prisoners.','They interred the remains.','第一句中 intern 是实习生。'),Q('intern',4,2,'Which spelling distinguishes burial from a trainee?','interred means buried; intern can mean a trainee','intern always means a burial','interred means a short work placement','interred 与埋葬相关，intern 可指实习生。')]);

P('internally','internally is formed from internal plus -ly and means within the inside of something or within an organization.',C('internally.s1','组织沟通','The research unit discussed the budget internally before presenting a single proposal to the university board.','研究部门在向大学董事会提交一份提案前，先在内部讨论了预算。','The research unit discussed the budget internally / before presenting / a single proposal / to the university board.','internally 修饰 discussed，表示讨论发生在组织内部；before 引出向外提交前的步骤。','先由部门成员内部讨论，符合 s1。'),M('The unit discussed the budget internally by sending it to every unrelated organization and holding no private discussion.','The unit discussed the budget publicly because it sent the proposal outside the organization.','向所有外部组织公开讨论不属于内部进行。'),[Q('internally',1,1,'To discuss an issue internally is to discuss it?','within the organization or group','only with unrelated outsiders','between two planets','internally 表示在内部。'),Q('internally',2,1,'The research unit discussed the budget internally before it?','presented a proposal to the university board','posted it publicly before any discussion','moved its office to another galaxy','内部讨论先于对外提交提案。'),Q('internally',3,1,'Which sentence uses internally naturally?','The company resolved the staffing issue internally.','The company internally between three planets.','The issue was internalizedly by staff.','internally 可修饰在组织内部解决问题。'),Q('internally',4,1,'The adjective corresponding to internally is?','internal','intertidal','intermittent','internally 由 internal 加 -ly 构成。')]);
P('internationalist','internationalist combines international and -ist; it may name a supporter of cooperation among nations or a specialist in international affairs.',C('internationalist.s1','外交政策讨论','As an internationalist, the senator argued that shared climate standards would benefit countries on both sides of the border.','作为一名国际主义者，这位参议员认为共同的气候标准会让边境两侧的国家都受益。','As an internationalist / the senator argued / that shared climate standards / would benefit countries on both sides of the border.','internationalist 作同位语，说明参议员支持国家间合作；that 从句给出主张内容。','主张跨国合作制定共同标准，符合 s1。'),M('The senator called herself an internationalist while insisting that every country avoid all cooperation and contact.','The senator rejected international cooperation rather than supporting it.','反对所有跨国合作与 internationalist 的合作理念相悖。'),[Q('internationalist',1,1,'An internationalist may support?','cooperation among different nations','the permanent isolation of every country','the division of one atom','internationalist 可指支持国家间合作的人。'),Q('internationalist',2,2,'The senator used internationalist in the sense of?','a person favoring cooperation between countries','a specialist who translates software code','a citizen who never discusses foreign policy','该句表达支持跨国合作的立场。'),Q('internationalist',3,1,'Which phrase is natural?','an internationalist approach to climate policy','an internationalist that excludes every nation','an internationalist between two shoes','internationalist 可修饰跨国合作的政策立场。'),Q('internationalist',4,2,'A second possible use of internationalist is?','a specialist in international affairs or law','a device for measuring distance','a person who studies only one family','该词也可指国际事务或国际法专家。')]);
P('internationalization','internationalization is formed from internationalize plus -ation and names the process of extending across national borders.',C('internationalization.s1','软件产品本地化','The internationalization of the software began with support for multiple writing systems, date formats, and currencies.','这款软件的国际化从支持多种文字系统、日期格式和货币开始。','The internationalization of the software / began with support / for multiple writing systems / date formats, and currencies.','internationalization 作主语中心词；多个区域设置说明产品适配不同国家。','软件为不同国家和语言环境扩展支持，符合 s1。'),M('The company described the software as undergoing internationalization even though it removed every language except one and served only one town.','The software remained local because it supported only one language and one market.','仅服务一个本地市场并未扩展到跨国环境。'),[Q('internationalization',1,1,'Internationalization is the process of?','extending activity or systems across national borders','reducing a service to one household','interlocking gears inside one machine','internationalization 指走向国际、跨国扩展的过程。'),Q('internationalization',2,1,'Which change can support software internationalization?','adding date formats and writing systems for other markets','deleting all language options but one','removing currency settings for every user','适配文字、日期和货币有助于跨国使用。'),Q('internationalization',3,1,'Which phrase is natural?','the internationalization of a product','the internationalization of one sealed drawer between two walls','an internationalization quickly run','internationalization 可指产品国际化过程。'),Q('internationalization',4,1,'The verb related to internationalization is?','internationalize','interrogate','interlock','internationalize 是其动词形式。')]);
P('internecine','internecine comes from Latin internecinus, associated with mutual slaughter; it describes destructive conflict within a group or between opposing sides.',C('internecine.s1','政党分裂','The internecine feud between rival factions consumed the party’s energy and drove several experienced members away.','敌对派系之间的内讧耗尽了该党的精力，还使几位资深成员离开。','The internecine feud / between rival factions / consumed the party’s energy / and drove several experienced members away.','internecine 修饰 feud，强调冲突发生在同一党内且具有破坏性。','同一组织内斗争消耗资源并造成损失，符合 s1。'),M('The conflict was internecine although all sides cooperated peacefully and none suffered harm or loss.','The conflict was peaceful because the factions cooperated without harming one another.','没有伤害或破坏的和平协作不符合 internecine。'),[Q('internecine',1,1,'An internecine conflict is typically?','destructive fighting within a group or between sides','a friendly conversation with no disagreement','a short break between performances','internecine 指破坏性的内斗或互相伤害。'),Q('internecine',2,1,'Why was the party feud internecine?','rival factions inside it damaged the same organization','the party held a peaceful celebration','the disagreement involved no people or consequences','党内派系互相消耗，体现内讧。'),Q('internecine',3,1,'Which phrase is natural?','an internecine struggle between factions','an internecine picnic with no conflict','an internecine that means “intergalactic”','internecine 常修饰冲突、斗争。'),Q('internecine',4,1,'Internecine is associated with?','mutual destruction or harmful internal conflict','a process of measuring waves','a guaranteed peaceful agreement','词义关联互相伤害和破坏性冲突。')]);
P('internship','internship is formed from intern plus -ship and means a temporary supervised work placement for practical experience.',C('internship.s1','工程学习','During her engineering internship, Leila helped test prototypes while an experienced designer reviewed her work.','在工程实习期间，莱拉协助测试原型，并由一位资深设计师审核她的工作。','During her engineering internship / Leila helped test prototypes / while an experienced designer / reviewed her work.','internship 指实习期；while 从句说明工作受到指导和审核。','短期实践岗位由资深人员指导，符合 s1。'),M('Leila called the placement an internship although it was a permanent unsupervised job with no training or practical learning.','Leila accepted a permanent independent position rather than a supervised internship.','永久且无指导的正式岗位不符合实习的短期学习性质。'),[Q('internship',1,1,'An internship is usually?','a temporary work placement for practical experience','a permanent post with no learning component','a legal list of questions','internship 指实习。'),Q('internship',2,1,'What did Leila do during the internship?','tested prototypes under an experienced designer’s review','ran the entire company without guidance','attended no workplace or training','实习中她进行实践并接受资深设计师审核。'),Q('internship',3,1,'Which phrase is natural?','apply for a summer internship','interview an internship between two planets','internship a prototype carefully','常见表达 apply for an internship。'),Q('internship',4,1,'An intern may take part in an?','internship','intertidal zone','interrogatory','internship 是实习生参与的实践岗位。')]);
P('interpersonal','interpersonal combines inter- and personal, describing relations, communication, or conflict between people.',C('interpersonal.s1','职场沟通','The workshop used role-play to help new managers handle interpersonal disagreements without embarrassing their colleagues.','这次培训通过角色扮演帮助新任经理处理人际分歧，同时避免让同事难堪。','The workshop used role-play / to help new managers handle interpersonal disagreements / without embarrassing / their colleagues.','interpersonal 修饰 disagreements，说明分歧发生在人与人之间。','经理处理同事关系中的分歧，符合 s1。'),M('The workshop addressed interpersonal conflict even though it concerned a single person alone in a room with no contact with others.','The workshop addressed solitary decision-making rather than relations between people.','完全没有人际接触的个人独处问题不是人际冲突。'),[Q('interpersonal',1,1,'Interpersonal relations occur?','between people','inside a single molecule only','between two ice ages','interpersonal 指人与人之间的。'),Q('interpersonal',2,1,'An interpersonal disagreement might involve?','two colleagues resolving a difference','one person working alone with no contact','a train changing from rail to ship','同事间分歧属于人际关系。'),Q('interpersonal',3,1,'Which phrase is natural?','interpersonal communication skills','interpersonal between one sealed object','interpersonally a disagreement','interpersonal 可修饰沟通技巧。'),Q('interpersonal',4,1,'The prefix inter- here means?','between or among people','inside one person’s body','without any personal contact','inter- 表示人与人之间。')]);
P('interplanetary','interplanetary combines inter- “between” and planetary, referring to space, travel, or communication between planets.',C('interplanetary.s1','太空任务','The mission plan includes an interplanetary cruise from Earth to Mars lasting several months.','任务计划包括一次从地球飞往火星、持续数月的行星际航行。','The mission plan includes / an interplanetary cruise / from Earth to Mars / lasting several months.','interplanetary 修饰 cruise，说明航行发生在不同星球之间；分词短语说明时长。','地球与火星是两颗不同星球，航程符合 s1。'),M('The route was interplanetary although the vehicle never left Earth and traveled only between two rooms.','The route was local because the vehicle stayed inside one building.','未离开地球的室内移动不是行星际航行。'),[Q('interplanetary',1,1,'Interplanetary travel takes place?','between planets','only between two rooms on Earth','between neighboring galaxies only','interplanetary 指行星之间的。'),Q('interplanetary',2,1,'An interplanetary cruise might travel from?','Earth to Mars','one desk to another','one star to another inside a distant galaxy','地球到火星是行星之间的航行。'),Q('interplanetary',3,1,'Which phrase is natural?','an interplanetary spacecraft','an interplanetary hallway inside a house','interplanetary the planet quickly','interplanetary 可修饰 spacecraft。'),Q('interplanetary',4,1,'Interplanetary differs from intergalactic because it is between?','planets rather than galaxies','people rather than departments','ice ages rather than stars','行星际涉及行星，星系际涉及星系。')]);
P('interplay','interplay names the way two or more things affect one another; as a verb, it can mean to act on one another.',C('interplay.s1','经济分析','The report examines the interplay of wages and housing costs, showing how each can influence migration to the city.','报告考察工资与住房成本之间的相互作用，说明二者如何共同影响迁入城市的人口。','The report examines the interplay of wages and housing costs / showing how each / can influence migration / to the city.','interplay 作名词，指工资与住房成本的相互影响；how 从句说明这种作用的结果。','报告展示两种因素互相影响迁移选择，符合 s1。'),M('The report described an interplay between wages and rent although neither could affect the other in any way.','The report found no interplay because wages and rent had no effect on one another.','互不影响就不构成相互作用。'),[Q('interplay',1,1,'The interplay of two factors is?','the way they affect one another','a list of unrelated items','a formal interview with one factor','interplay 指相互作用。'),Q('interplay',2,2,'Wages and housing costs interplay when?','a change in either can influence migration','they are kept in separate books and have no effects','both are measured but never compared','报告指出工资和住房成本共同影响人口迁移。'),Q('interplay',3,1,'Which phrase is natural?','the interplay between culture and technology','the interplay of two factors that never interact','interplay a noun with no relationship','常见结构 the interplay between...and...。'),Q('interplay',4,2,'Interplay can also be used as a verb meaning?','act on or affect one another','question someone formally','stop and start at intervals','动词 interplay 可表示相互作用。')]);
P('interpretation','interpretation comes from interpret plus -ation and can mean an explanation of meaning or a particular performance or rendering.',C('interpretation.s1','数据分析','The analyst offered a cautious interpretation of the survey, noting that a small sample could not prove causation.','分析员谨慎地解释了这项调查，并指出小样本无法证明因果关系。','The analyst offered / a cautious interpretation of the survey / noting that a small sample / could not prove causation.','interpretation 指对调查结果的解释；noting 补充该解释保持谨慎的理由。','说明数据含义并承认局限，符合 s1。'),M('The analyst called the claim an interpretation even though it introduced no explanation of what the survey meant.','The analyst gave no interpretation because the claim did not explain the survey results.','完全没有解释数据含义就不构成 interpretation。'),[Q('interpretation',1,1,'An interpretation of data is?','an explanation of what the data may mean','a list of data with no comment','a person who answers interview questions','interpretation 可指对含义的解释。'),Q('interpretation',2,1,'Why was the survey interpretation cautious?','a small sample could not establish causation','the sample contained every person in the world','the survey had no data to examine','小样本不能证明因果，解释需谨慎。'),Q('interpretation',3,1,'Which phrase is natural?','a possible interpretation of the poem','an interpretation that refuses to explain any meaning','interpretation the analyst carefully','interpretation 可作名词并由 of 引出对象。'),Q('interpretation',4,2,'Interpretation can also refer to?','a particular performance or rendering of a work','a person confined during wartime','a brief pause between performances','interpretation 也指作品的演绎方式。')]);
P('interpreter','interpreter comes from interpret plus -er and may be an oral translator or a person who explains or executes something.',C('interpreter.s1','医疗沟通','The interpreter translated the patient’s questions into the doctor’s language and then conveyed the answers back accurately.','口译员把病人的问题译成医生使用的语言，再准确地把回答传回给病人。','The interpreter translated the patient’s questions / into the doctor’s language / and then conveyed the answers / back accurately.','interpreter 作名词，指口头翻译者；translated 与 conveyed back 描述双向传译。','此人当场在两种语言之间传话，符合 s1。'),M('The interpreter helped both speakers by refusing to translate either question or answer.','The interpreter failed to help because no spoken message was translated.','不翻译双方话语就没有承担口译工作。'),[Q('interpreter',1,1,'An interpreter at a meeting usually?','translates spoken messages between languages','repairs the meeting room furniture','writes a legal indictment','interpreter 可指口译员。'),Q('interpreter',2,1,'What did the medical interpreter do?','conveyed the patient’s questions and doctor’s answers','kept both speakers from communicating','diagnosed the patient without listening','口译员双向传达问题与回答。'),Q('interpreter',3,1,'Which phrase is natural?','a sign-language interpreter','an interpreter a language fluently yesterday','an interpretable who translates speech','interpreter 可指手语口译员。'),Q('interpreter',4,2,'A computing interpreter may?','execute code instructions as it reads them','translate between two spoken languages only','question a witness in court','该词也可指逐步执行代码的程序。')]);
P('interrelate','interrelate combines inter- and relate; things may be connected with one another, or someone may show how they connect.',C('interrelate.s1','科学研究','The researchers showed how sleep and memory interrelate by comparing recall scores after different rest periods.','研究人员比较不同休息时长后的回忆得分，展示睡眠与记忆如何相互关联。','The researchers showed / how sleep and memory interrelate / by comparing recall scores / after different rest periods.','interrelate 在此是不及物动词，说明睡眠与记忆相互关联；by 引出研究方法。','研究发现两者的变化存在关联，符合 s1。'),M('The researchers said sleep and memory interrelate even though changes in either never corresponded to or affected the other.','The researchers found no relation because neither variable influenced the other.','变化没有任何联系就不能说 interrelate。'),[Q('interrelate',1,1,'If two factors interrelate, they?','are connected with or affect one another','are guaranteed to be identical','are locked in separate sealed containers','interrelate 表示相互关联。'),Q('interrelate',2,1,'The researchers compared recall after rest periods to?','show how sleep and memory are connected','prove that memory is a type of furniture','avoid measuring either factor','比较得分用于展示睡眠与记忆的联系。'),Q('interrelate',3,1,'Which sentence is natural?','The findings interrelate several social factors.','The findings interrelately the factors yesterday.','The factors are interrelate with sleep.','interrelate 可描述因素相互关联。'),Q('interrelate',4,2,'Interrelate can also mean to?','show or establish connections between things','translate speech aloud','make a trip between planets','及物用法可表示揭示事物间联系。')]);
P('interrelationship','interrelationship combines inter-, relation, and -ship and means a connection in which elements affect one another.',C('interrelationship.s1','环境管理','The interrelationship between forest cover and stream temperature shaped the conservation plan for the watershed.','森林覆盖与溪流水温之间的相互关系决定了该流域保护计划的制定。','The interrelationship between forest cover and stream temperature / shaped the conservation plan / for the watershed.','interrelationship 作主语，between 引出相互关联的两项因素。','保护计划依据两因素互相影响的关系制定，符合 s1。'),M('The planner described an interrelationship between forest cover and stream temperature although neither variable affected the other.','The planner found no relationship because the two variables were unrelated.','没有相互影响的两个变量不能称为 interrelationship。'),[Q('interrelationship',1,1,'An interrelationship is a connection where?','elements relate to or affect one another','each element is completely unrelated','one item is only measured once','interrelationship 指相互关联。'),Q('interrelationship',2,1,'Why did forest cover and stream temperature matter together?','their relationship shaped a watershed plan','they were two names for the same tree','neither influenced the conservation decision','二者的相互关系影响保护方案。'),Q('interrelationship',3,1,'Which phrase is natural?','the interrelationship between diet and health','an interrelationship with nothing related','the interrelationship of one item only','常见结构 interrelationship between two factors。'),Q('interrelationship',4,1,'The word contains the idea of?','a relation among connected parts','a brief scene between performances','a device to detect wave differences','词形包含关系与相互联系的概念。')]);
P('interrogation','interrogation comes from Latin interrogare, “ask”; it often means formal or prolonged questioning by an authority.',C('interrogation.s1','刑侦程序','After the interrogation, the detective compared the witness’s account with the security footage before filing a report.','询问结束后，侦探在提交报告前把证人的陈述与监控录像进行了对照。','After the interrogation / the detective compared the witness’s account / with the security footage / before filing a report.','interrogation 指正式询问；after 引出询问结束后的核查步骤。','证人受到正式问询，符合 s1。'),M('The police recorded an interrogation although they asked the witness no questions and held no formal interview.','The police held no interrogation because they did not question the witness.','没有提问或正式问询就不是 interrogation。'),[Q('interrogation',1,1,'An interrogation is often?','formal or sustained questioning','a short pause between songs','a type of interplanetary trip','interrogation 指正式或持续询问。'),Q('interrogation',2,1,'What did the detective do after the interrogation?','compared the account with security footage','forgot to ask any questions','changed the witness’s identity','询问后将证词与监控进行核实。'),Q('interrogation',3,1,'Which phrase is natural?','a police interrogation','an interrogation between two glaciers','interrogation a witness politely','police interrogation 是自然搭配。'),Q('interrogation',4,1,'Interrogation is formed from a verb meaning?','to ask','to lock together','to grow between ice ages','其词源动词 interrogare 表示询问。')]);
P('interrogatory','interrogatory derives from interrogate and may describe a questioning tone or a formal written set of questions.',C('interrogatory.s1','法庭问答','The lawyer adopted an interrogatory tone, asking the witness for exact times and names rather than inviting a general story.','律师采用质询式语气，要求证人给出确切时间和姓名，而不是请其泛泛讲述。','The lawyer adopted an interrogatory tone / asking the witness / for exact times and names / rather than inviting a general story.','interrogatory 修饰 tone，表示带有提问、盘问性质；rather than 对照两种问话方式。','律师逐项要求具体答案，体现质询语气，符合 s1。'),M('The lawyer used an interrogatory tone by making no inquiries and allowing only an uninterrupted speech.','The lawyer used a non-questioning tone because no questions were asked.','完全不提问的语气不是 interrogatory。'),[Q('interrogatory',1,1,'An interrogatory tone sounds?','questioning or probing','silent and without any inquiry','like a musical instrument only','interrogatory 可形容质询式语气。'),Q('interrogatory',2,1,'The lawyer’s questions asked for?','specific names and times','a general story with no details','a translation of computer code','逐项询问姓名和时间体现盘问。'),Q('interrogatory',3,1,'Which phrase is natural?','an interrogatory manner of questioning','an interrogatory silence with no questions','an interrogatory between two planets','interrogatory 可修饰问话方式。'),Q('interrogatory',4,2,'Interrogatory may also name?','a formal written set of questions in a legal case','a short interlude in a concert','a student work placement','它也可指诉讼中的书面问题清单。')]);
P('interruption','interruption is formed from interrupt plus -ion and means an event or act that breaks the continuity of something.',C('interruption.s1','线上授课','A brief internet interruption cut off the lecture, so the instructor repeated the last example after the connection returned.','短暂的网络中断切断了讲课，因此网络恢复后讲师重新讲解了最后一个例子。','A brief internet interruption / cut off the lecture / so the instructor repeated / the last example after the connection returned.','interruption 作主语，表示打断连续讲课的事件；so 引出补讲的结果。','网络故障使讲课暂时中断，符合 s1。'),M('The lecture had an interruption even though it continued without pause, loss of connection, or any break.','The lecture continued uninterrupted because there was no break at all.','完全没有停顿的讲课没有 interruption。'),[Q('interruption',1,1,'An interruption is something that?','breaks the continuity of an activity','makes an activity happen without any pause','is a person who answers questions','interruption 指中断。'),Q('interruption',2,1,'Why did the instructor repeat the example?','an internet interruption cut off the lecture','the lecture had never started','the connection was perfect throughout','网络中断造成内容缺失，恢复后需重讲。'),Q('interruption',3,1,'Which phrase is natural?','a brief interruption to the meeting','an interruption that never interrupts anything','interruption between two planets','interruption 可指会议中的短暂打断。'),Q('interruption',4,1,'The verb related to interruption is?','interrupt','interlock','intermix','interrupt 是其动词形式。')]);
P('intersected','intersected is the past form or participle of intersect, meaning that lines, routes, or surfaces crossed one another or crossed something.',C('intersected.s1','地图阅读','On the old map, the walking trail intersected the river just below the stone bridge.','在旧地图上，这条步道在石桥正下方与河流相交。','On the old map / the walking trail intersected the river / just below / the stone bridge.','intersected 是及物动词过去式，表示步道穿过或与河道相交；below 说明交点位置。','地图上的路线与河流有交点，符合 s1。'),M('The trail intersected the river even though the two remained parallel and never crossed or met.','The trail ran parallel to the river and did not intersect it.','平行且不相交的路线不满足 intersected。'),[Q('intersected',1,1,'Two lines intersect when they?','cross or meet at a point','remain parallel forever','are questioned by a lawyer','intersect 表示相交。'),Q('intersected',2,1,'Where did the trail intersect the river?','just below the stone bridge','inside the sun','at a point where it never met the river','路线在石桥下方与河相交。'),Q('intersected',3,1,'Which sentence is grammatical?','The roads intersected near the market.','The roads were intersected near the market yesterdayly.','The roads intersecting near the market last week.','intersected 可作过去式。'),Q('intersected',4,1,'The base verb is?','intersect','intercede','interweave','intersected 的原形是 intersect。')]);
P('interstate','interstate combines inter- “between” and state, describing something involving two or more states within a country.',C('interstate.s1','美国公路旅行','Their interstate bus crossed from Ohio into Pennsylvania before continuing east toward New York.','他们乘坐的州际巴士从俄亥俄州进入宾夕法尼亚州，然后继续向东前往纽约。','Their interstate bus crossed / from Ohio into Pennsylvania / before continuing east / toward New York.','interstate 修饰 bus，表示跨州运行；from...into...标出跨越州界。','巴士经过不止一个州，符合 s1。'),M('The route was interstate although the bus stayed inside one state and never crossed a state boundary.','The route was intrastate because it remained within one state.','只在单一州内运行属于州内而非州际。'),[Q('interstate',1,1,'An interstate route involves?','two or more states','only one neighborhood street','several planets','interstate 指州与州之间的。'),Q('interstate',2,1,'Why was the bus trip interstate?','it crossed from Ohio into Pennsylvania','it stayed within one terminal','it traveled between two rooms','路线穿过州界，涉及多个州。'),Q('interstate',3,1,'Which phrase is natural?','interstate commerce between states','interstate inside one town only','an interstate a road quickly','interstate commerce 是常见搭配。'),Q('interstate',4,1,'The prefix inter- in interstate means?','between','within one','without','inter- 表示州与州之间。')]);
P('interstellar','interstellar combines inter- “between” and stellar, referring to the space or travel between stars.',C('interstellar.s1','科幻设定','The novel imagines an interstellar voyage lasting decades as the crew travels from one star system to another.','小说设想了一次持续数十年的星际航行，船员从一个恒星系前往另一个恒星系。','The novel imagines / an interstellar voyage / lasting decades / as the crew travels from one star system to another.','interstellar 修饰 voyage，说明航程位于恒星之间；as 引出船员进行的旅程。','从一个恒星系到另一个恒星系属于恒星际航行，符合 s1。'),M('The journey was interstellar although the spacecraft never left one planet and traveled only across a single room.','The journey was local because it stayed inside one building.','没有跨越恒星系的旅程不是星际航行。'),[Q('interstellar',1,1,'Interstellar space is space?','between stars','between two people in a room','between two tides on one beach','interstellar 指恒星之间的。'),Q('interstellar',2,1,'An interstellar voyage might travel?','from one star system to another','from one desk to another','from one state to a neighboring state','不同恒星系之间的航行符合词义。'),Q('interstellar',3,1,'Which phrase is natural?','interstellar travel','interstellar inside one kitchen','interstellarly voyage','interstellar 可修饰 travel。'),Q('interstellar',4,1,'Interstellar differs from interplanetary because it is between?','stars rather than planets','communities rather than people','ice ages rather than galaxies','恒星际涉及恒星，行星际涉及行星。')]);
P('interstitial','interstitial comes from Latin interstitium, “interval”; it describes something located in the small spaces or gaps within a structure.',C('interstitial.s1','医学影像','The scan showed interstitial fluid collecting in the narrow spaces between the tissue cells.','扫描显示组织细胞之间的狭窄间隙中积聚了间质液。','The scan showed interstitial fluid / collecting in the narrow spaces / between the tissue cells.','interstitial 修饰 fluid，说明它位于组织结构内部的细小空隙；collecting 补充影像发现。','液体聚集于细胞之间的间隙，符合 s1。'),M('The fluid was interstitial although it lay only on the outer surface and never entered any gap within the tissue.','The fluid was external because it remained on the tissue’s outer surface.','只在外表面、不在内部空隙中的液体不是 interstitial。'),[Q('interstitial',1,1,'Interstitial spaces are?','small gaps within a larger structure','the outside edge of a distant galaxy','a long period between ice ages','interstitial 指结构内部的小间隙。'),Q('interstitial',2,1,'Where did the scan find the fluid?','between the tissue cells','only on the outside of the skin','inside a star system far away','细胞间隙是组织的内部空间。'),Q('interstitial',3,1,'Which phrase is natural?','interstitial fluid in tissue','interstitial beyond every structure','interstitially fluid','interstitial 可修饰医学名词 fluid。'),Q('interstitial',4,1,'The word is associated with an?','interval or space between parts','interview for a job','international political movement','词源词 interstitium 表示间隔或空隙。')]);
P('intertidal','intertidal combines inter- and tidal, describing the shore zone covered by water at high tide and exposed at low tide.',C('intertidal.s1','海岸生态','Crabs and mussels occupy the intertidal zone, where they must tolerate both seawater and periods of exposure to air.','螃蟹和贻贝生活在潮间带，必须适应海水覆盖和暂时暴露在空气中的交替环境。','Crabs and mussels occupy the intertidal zone / where they must tolerate / both seawater / and periods of exposure to air.','intertidal 修饰 zone；where 从句说明生物面对潮汐变化的环境。','该地带涨潮时被淹、退潮时露出，符合 s1。'),M('The beach was intertidal although it stayed permanently dry and was never reached by high tide.','The beach was an upland area because the tide never covered it.','潮水永远无法到达的干燥高地不是潮间带。'),[Q('intertidal',1,1,'The intertidal zone is covered by water?','at high tide and exposed at low tide','at every hour with no change','only during an ice age','潮间带随潮位覆盖与裸露。'),Q('intertidal',2,1,'Why must intertidal animals tolerate exposure to air?','the shore is uncovered when the tide falls','they live permanently under deep water','they travel between galaxies','退潮时潮间带会暴露在空气中。'),Q('intertidal',3,1,'Which phrase is natural?','intertidal organisms on a rocky shore','intertidal organisms in a desert far inland','intertidally zone','intertidal 可修饰生物和区域。'),Q('intertidal',4,1,'The word tidal refers to?','tides or the rise and fall of sea level','the process of translating speech','the distance between galaxies','tidal 与潮汐有关。')]);

P('intertwine','intertwine combines inter- and twine, meaning to twist things together or to connect them closely.',C('intertwine.s1','园艺维护','The gardener trained the young bean vines to intertwine around a light wooden frame.','园丁引导嫩豆藤缠绕在轻木架上生长。','The gardener trained the young bean vines / to intertwine / around a light wooden frame.','intertwine 是不定式动词，说明藤蔓彼此缠绕的方式；around 引出支撑物。','豆藤相互缠绕在架子上，符合 s1。'),M('The vines intertwined although they grew in separate rooms and never touched or crossed one another.','The vines grew separately because they never touched or crossed.','互不接触的藤蔓没有缠绕在一起。'),[Q('intertwine',1,1,'To intertwine strands is to?','twist them together','keep each one entirely separate','question each strand formally','intertwine 指缠绕或编织在一起。'),Q('intertwine',2,2,'Ideas can intertwine when they?','connect closely and affect one another','remain unrelated and never overlap','are measured with a telescope','抽象事物也可紧密交织。'),Q('intertwine',3,1,'Which phrase is natural?','vines intertwine around a trellis','vines intertwine apart from every support','vines are intertwiningly a garden','藤蔓可缠绕支架生长。'),Q('intertwine',4,2,'Which can intertwine metaphorically?','two characters’ lives in a novel','a sealed container with no links','a tide and a stopwatch in unrelated settings','生活或故事线可以比喻性交织。')]);
P('intervention','intervention is formed from intervene plus -tion and means becoming involved to alter or improve a situation.',C('intervention.s1','公共卫生','Early intervention helped the clinic treat the infection before it spread to other residents of the shelter.','及早干预使诊所在感染传播给避难所其他居民前就进行了治疗。','Early intervention / helped the clinic treat the infection / before it spread / to other residents of the shelter.','intervention 指为改变事态而介入；before 从句说明介入的时机和目的。','及时采取措施阻止传播，符合 s1。'),M('The clinic called its response an intervention although it took no action and allowed the infection to spread unchecked.','The clinic did not intervene because it took no action to change the situation.','没有介入或采取措施就不能称为 intervention。'),[Q('intervention',1,1,'An intervention is an act of?','becoming involved to change what is happening','watching events without taking any action','translating speech between languages','intervention 指介入、干预。'),Q('intervention',2,1,'Why was the clinic’s intervention early?','it treated the infection before it spread','it waited until every resident was ill','it stopped offering any care','在传播前治疗体现及早干预。'),Q('intervention',3,1,'Which phrase is natural?','a timely intervention by the teacher','an intervention that takes no action at all','intervention between two stars','intervention 可指及时干预。'),Q('intervention',4,1,'The verb related to intervention is?','intervene','intertwine','interrogate','intervene 是其动词形式。')]);
P('interviewee','interviewee is formed from interview plus -ee, a suffix often marking the person who receives an action; it is the person answering questions.',C('interviewee.s1','求职面试','The interviewee described her experience with the lab equipment while the hiring panel took notes.','应聘者介绍了自己使用实验室设备的经验，同时招聘小组做着记录。','The interviewee described her experience / with the lab equipment / while the hiring panel / took notes.','interviewee 作主语，指接受提问、回答问题的人；while 从句说明面试官在做什么。','她回答招聘小组的问题，符合 s1。'),M('The interviewee led the panel’s questioning and never answered a single question herself.','The interviewer led the questioning, while the interviewee answered it.','主导提问者是 interviewer；interviewee 通常是回答问题的人。'),[Q('interviewee',1,1,'An interviewee is usually the person who?','answers questions in an interview','conducts every question as the interviewer','repairs the interview room','interviewee 指接受采访或面试的人。'),Q('interviewee',2,1,'What did the interviewee describe?','her experience with lab equipment','the panel’s private notes only','a route between two planets','应聘者介绍自己的工作经验。'),Q('interviewee',3,1,'Which pair is correctly matched?','interviewer asks; interviewee answers','interviewee asks; interviewer answers every time','interviewer and interviewee both mean “translator”','interviewer 提问，interviewee 回答。'),Q('interviewee',4,1,'The suffix -ee here points to someone who?','receives the interview or is interviewed','conducts the interview','is a temporary intern only','-ee 表示接受动作的一方。')]);
P('interviewer','interviewer is formed from interview plus -er and names a person who conducts an interview and asks the questions.',C('interviewer.s1','新闻采访','The interviewer asked the athlete how she recovered from the injury, then gave her time to explain the training plan.','采访者询问运动员如何从伤病中恢复，并留出时间让她解释训练计划。','The interviewer asked the athlete / how she recovered from the injury / then gave her time / to explain the training plan.','interviewer 作主语，表示提问的一方；how 从句引出问题内容。','此人提出问题并主持采访，符合 s1。'),M('The interviewer sat silently and answered every question while the guest conducted the entire interview.','The guest interviewed the host because the host did not ask questions.','不提问、由对方主持采访的人不是 interviewer。'),[Q('interviewer',1,1,'An interviewer is the person who?','asks questions and conducts an interview','answers every question as the guest','translates spoken languages only','interviewer 指采访或面试的提问者。'),Q('interviewer',2,1,'What did the interviewer ask the athlete about?','her recovery and training plan','the price of a telescope','the interviewer’s own job application','采访者询问运动员的伤病恢复和训练。'),Q('interviewer',3,1,'Which phrase is natural?','the interviewer asked a follow-up question','the interviewer was interviewed by herself in every case','the interviewee asked the question as interviewer','采访者可提出后续问题。'),Q('interviewer',4,1,'The suffix -er often names?','a person who performs an action','a person who receives an action only','the result of an action','-er 常指执行动作的人。')]);
P('interweave','interweave combines inter- and weave, meaning to weave strands together or to combine elements closely.',C('interweave.s1','小说写作','The novelist interwove three family histories so that an event in one generation changed the choices of the next.','小说家把三个家族的历史交织在一起，使一代人的事件改变了下一代的选择。','The novelist interwove three family histories / so that an event in one generation / changed the choices / of the next.','interwove 是 interweave 的过去式，表示把多条故事线交织起来；so that 表示结果。','多条家族历史互相交错并影响彼此，符合 s1。'),M('The novelist interwove the stories while keeping each one completely separate, unrelated, and unable to affect another.','The novelist kept the stories separate instead of weaving them together.','彼此完全分开、互不影响的故事没有被交织。'),[Q('interweave',1,1,'To interweave stories is to?','combine them closely so they cross and connect','keep each story isolated from every other','question each character in court','interweave 可表示交织故事线。'),Q('interweave',2,1,'How did the generations connect in the novel?','events in one history affected later choices','each family story remained sealed off','the novel contained no events or characters','不同代际的故事互相影响。'),Q('interweave',3,1,'Which phrase is natural?','interweave fact with personal narrative','interweave two strands while keeping them apart','interweave to the sky yesterday','interweave 可表示把事实与叙述结合。'),Q('interweave',4,1,'Interweave can refer to?','weaving strands or combining elements','a person answering interview questions','a shore zone between tides','该词既可指织线，也可指组合内容。')]);
P('intestinal','intestinal derives from intestine plus -al and means relating to the intestines.',C('intestinal.s1','医学说明','The scan showed intestinal inflammation, so the doctor recommended further tests before changing the patient’s diet.','扫描显示肠道有炎症，因此医生建议先做进一步检查，再调整患者饮食。','The scan showed intestinal inflammation / so the doctor recommended / further tests / before changing the patient’s diet.','intestinal 修饰 inflammation，说明炎症位于肠道；so 引出医生建议。','检查发现肠道问题，符合 s1。'),M('The report called the condition intestinal although it affected only the skin and had no connection to the digestive tract.','The condition was dermatological because it affected the skin, not the intestine.','只影响皮肤而与肠道无关的病症不是 intestinal。'),[Q('intestinal',1,1,'Intestinal means?','relating to the intestines','relating only to the outer skin','located between two galaxies','intestinal 指与肠有关的。'),Q('intestinal',2,1,'What did the scan show?','inflammation in the digestive tract','an injury to the ankle','a break in an electrical cable','扫描发现肠道炎症。'),Q('intestinal',3,1,'Which phrase is natural?','intestinal health','intestinal interviewee','intestinal between two planets','intestinal 可修饰 health。'),Q('intestinal',4,1,'The noun at the root of intestinal is?','intestine','interview','intervention','intestinal 由 intestine 派生。')]);
P('intimacy','intimacy comes from intimate plus -cy and can mean close personal friendship or a detailed, familiar knowledge of something.',C('intimacy.s1','人物关系','The intimacy between the sisters was clear in the shorthand jokes and quiet support they shared during the move.','姐妹之间的亲密关系体现在搬家时彼此心照不宣的玩笑和默默支持中。','The intimacy between the sisters / was clear / in the shorthand jokes / and quiet support they shared during the move.','intimacy 指人与人之间亲近的关系；between 引出双方。','姐妹间有深厚信任与亲近感，符合 s1。'),M('The sisters had intimacy despite never speaking, trusting, or supporting one another and avoiding all contact.','The sisters had no close relationship because they avoided contact and trust.','没有交流、信任或支持，不符合亲密关系之义。'),[Q('intimacy',1,1,'Intimacy between people involves?','close personal familiarity or affection','complete unfamiliarity and no contact','a legal written questionnaire','intimacy 可指亲密关系。'),Q('intimacy',2,1,'What showed the sisters’ intimacy?','shared jokes and mutual support','their refusal ever to communicate','the distance between two galaxies','相互理解和支持体现亲密。'),Q('intimacy',3,1,'Which phrase is natural?','a relationship of great intimacy','an intimacy that means no contact at all','intimacy the people close yesterday','intimacy 可描述亲密关系。'),Q('intimacy',4,2,'Intimacy can also mean?','detailed familiarity with a subject','a temporary job placement','a sudden formal interrogation','该词也可指对某事物的深入熟悉。')]);
P('intimately','intimately is the adverb from intimate; it can mean in a close personal way or with detailed familiarity.',C('intimately.s2','专业知识','The archivist knew the collection intimately and could identify a document by its paper, handwriting, and date.','档案管理员对这批藏品了如指掌，能根据纸张、笔迹和日期辨认文献。','The archivist knew the collection intimately / and could identify a document / by its paper, handwriting, / and date.','intimately 修饰 knew，表示对藏品细节非常熟悉；by 列出判断依据。','能从细节辨认文献，体现深入了解，符合 s2。'),M('The archivist knew the collection intimately although she had never seen it, could identify no details, and knew nothing about it.','The archivist knew little about the collection because she had never seen or studied it.','从未接触且不了解细节不能称作 intimately 熟悉。'),[Q('intimately',1,2,'To know a collection intimately is to know it?','in great detail and with close familiarity','only from a distant rumor','without seeing or learning anything about it','intimately 可表示深入且熟悉地。'),Q('intimately',2,2,'Why did the archivist know the collection intimately?','she could identify documents from detailed features','she had never examined any document','she confused every date and handwriting sample','她能凭细节辨认文献，说明熟悉程度很深。'),Q('intimately',3,2,'Which sentence uses intimately naturally?','The guide knew the building intimately.','The guide intimately between two towns.','The building intimately knew the guide.','intimately 可修饰 know，表示非常熟悉。'),Q('intimately',4,1,'Intimately may also describe acting?','in a close personal way','at a great distance with no connection','at irregular intervals','它还可表示亲密地、私密地。')]);
P('intimidation','intimidation is formed from intimidate plus -ion and means frightening or threatening someone to make them feel afraid or comply.',C('intimidation.s1','校园举报','The school introduced a confidential reporting channel after students said intimidation had kept them from reporting bullying.','学生表示恐吓使他们不敢举报霸凌后，学校设立了保密举报渠道。','The school introduced a confidential reporting channel / after students said / intimidation had kept them / from reporting bullying.','intimidation 指以恐吓造成压力；had kept 表示此前持续阻止学生举报。','恐吓使学生不敢举报，符合 s1。'),M('The students described intimidation even though nobody threatened, frightened, pressured, or tried to control anyone.','The students described a calm exchange because no one threatened or pressured them.','没有威胁或施压的平静交流不构成 intimidation。'),[Q('intimidation',1,1,'Intimidation is the use of?','fear or threats to pressure someone','friendly advice with no pressure','a careful scientific measurement','intimidation 指恐吓或威胁。'),Q('intimidation',2,1,'What effect did intimidation have at the school?','it kept students from reporting bullying','it encouraged every student to report immediately','it measured the school building','恐吓使学生不敢举报。'),Q('intimidation',3,1,'Which phrase is natural?','a campaign against workplace intimidation','intimidation that frightens nobody or pressures no one','intimidate as a noun in every sentence','workplace intimidation 是自然搭配。'),Q('intimidation',4,1,'The verb related to intimidation is?','intimidate','interweave','interrelate','intimidate 是其动词形式。')]);
P('intonation','intonation names the rise and fall of the voice in speech and can also describe the tune used in chanting or reciting.',C('intonation.s1','语言课堂','Her rising intonation at the end of the sentence made the statement sound like a question.','她在句末上扬的语调让陈述句听起来像一个问题。','Her rising intonation / at the end of the sentence / made the statement / sound like a question.','intonation 指语音的升降模式；at the end 指具体的句末位置。','句末音高上扬改变了听者对话语功能的判断，符合 s1。'),M('The sentence had rising intonation although the voice stayed at one unchanging pitch from beginning to end.','The sentence had level intonation because the speaker’s pitch never rose or fell.','音高始终不变不属于 rising intonation。'),[Q('intonation',1,1,'Intonation in speech is the pattern of?','rising and falling voice pitch','spelling changes on a page','movement between two cities','intonation 指语调的升降模式。'),Q('intonation',2,1,'Why did the statement sound like a question?','the speaker’s pitch rose at the end','the speaker used no voice at all','the sentence contained no ending','句末升调常使话语听起来像疑问。'),Q('intonation',3,1,'Which phrase is natural?','a rising intonation pattern','an intonation of silent handwriting','intonationally question pitch is','rising intonation 是常见表达。'),Q('intonation',4,2,'Intonation can also refer to?','a tune used in chanting or reciting','a temporary supervised work placement','a formal written legal question list','intonation 也可指吟诵或诵读时的曲调。')]);
P('intone','intone comes from Latin intonare, “sound thunder”; it means to utter words in a slow, measured, often solemn or musical voice.',C('intone.s1','纪念仪式','The officiant intoned the names slowly, leaving a pause after each person so the audience could remember them.','主持人缓慢地念出每个人的名字，并在名字之间停顿，让听众有时间追思。','The officiant intoned the names slowly / leaving a pause / after each person / so the audience could remember them.','intoned 是及物动词，表示以庄重缓慢的声音念出；so 引出停顿的目的。','缓慢庄重地念名单，符合 s1。'),M('The officiant intoned the names by shouting them rapidly in a casual voice with no measured rhythm.','The officiant called out the names quickly and casually instead of intoning them.','快速随意地喊叫不符合缓慢庄重的 intone。'),[Q('intone',1,1,'To intone words is to say them?','in a slow, measured, often solemn voice','at random intervals with no voice','as fast as possible in a casual shout','intone 表示缓慢庄重地念。'),Q('intone',2,1,'How did the officiant intone the names?','slowly with pauses after each','by shouting all names as quickly as possible','by writing them silently on a wall','主持人缓慢念名并停顿。'),Q('intone',3,1,'Which phrase is natural?','intone a solemn prayer','intone a prayer silently without uttering it','intone a document into a telescope','intone 可带宾语，如 intone a prayer。'),Q('intone',4,1,'Intone is related to?','tone or sound','tide or shoreline','interview or employment','intone 与音调、发声有关。')]);
P('intoxicate','intoxicate is built from intoxication; it can mean to make someone drunk or to fill them with overwhelming excitement.',C('intoxicate.s1','食品安全','The contaminated drink could intoxicate anyone who consumed enough of it, so the laboratory issued an urgent warning.','这种受污染的饮料如果饮用过量可能使人中毒，因此实验室发布了紧急警告。','The contaminated drink / could intoxicate anyone / who consumed enough of it / so the laboratory issued an urgent warning.','intoxicate 在此指使人醉酒或中毒；who 从句说明风险条件。','饮用受污染液体可能造成中毒状态，符合 s1。'),M('The drink intoxicated the hikers even though it contained no active substance and produced no physical or mental effect.','The drink had no intoxicating effect because it contained no active substance.','没有作用的饮料不会使人醉或中毒。'),[Q('intoxicate',1,1,'To intoxicate someone can mean to?','make them drunk or affected by a toxic substance','make them fully alert with no effect','ask them questions in court','intoxicate 可表示使醉或中毒。'),Q('intoxicate',2,1,'Why did the laboratory issue a warning?','the contaminated drink could intoxicate consumers','the drink was completely harmless in any quantity','the drink had already evaporated','饮用污染饮料可能导致中毒。'),Q('intoxicate',3,1,'Which phrase is natural?','alcohol can intoxicate a person','intoxicate a person without any substance or effect','intoxicate is only a noun','酒精可以使人醉。'),Q('intoxicate',4,2,'Intoxicate can also mean to?','fill someone with overwhelming excitement','stop and start at intervals','connect two communities','该词也可比喻使人极度兴奋。')]);
P('intoxication','intoxication names the state of being affected by alcohol or a toxic substance, and can also describe extreme excitement.',C('intoxication.s1','交通安全','The driver was charged after a roadside test indicated alcohol intoxication and impaired reaction time.','路边检测显示司机酒精中毒且反应能力受损后，他受到了指控。','The driver was charged / after a roadside test indicated / alcohol intoxication / and impaired reaction time.','intoxication 指酒精造成的受影响状态；and 连接测试显示的两个问题。','检测发现酒精影响及反应变慢，符合 s1。'),M('The test showed intoxication even though the driver had consumed nothing and showed no effect from alcohol or drugs.','The test found no intoxication because there was no substance or impairment.','没有摄入任何物质且没有受影响，不符合 intoxication。'),[Q('intoxication',1,1,'Alcohol intoxication is a condition caused by?','being affected by too much alcohol','a person’s detailed knowledge of a topic','a question asked in a courtroom','intoxication 可指酒精影响状态。'),Q('intoxication',2,1,'What did the roadside test indicate?','alcohol had impaired the driver’s reaction time','the driver had never been tested','the road crossed a state boundary','检测提示酒精影响了驾驶反应。'),Q('intoxication',3,1,'Which phrase is natural?','signs of intoxication','intoxication that has no cause or effect','intoxicate as a condition noun','signs of intoxication 是自然搭配。'),Q('intoxication',4,2,'Intoxication can also describe?','great excitement that affects judgment','a formal written list of questions','a quiet interval between performances','它也可比喻极度兴奋而影响判断。')]);
P('intransigent','intransigent comes from Latin intransigens, “not yielding”; it describes someone unwilling to change a position or compromise.',C('intransigent.s2','劳资谈判','The intransigent negotiator rejected every compromise and insisted that the contract contain the original demand word for word.','这名不肯让步的谈判者拒绝了所有折中方案，坚持合同必须逐字保留最初的要求。','The intransigent negotiator / rejected every compromise / and insisted / that the contract contain the original demand word for word.','intransigent 修饰 negotiator，指不愿改变立场的人；rejected every compromise 展示其固执。','谈判者拒绝所有妥协，符合 s2。'),M('The negotiator was intransigent because she readily revised her position and accepted every reasonable compromise.','The negotiator was flexible because she adjusted her position and accepted compromise.','愿意修改立场并接受妥协与 intransigent 相反。'),[Q('intransigent',1,2,'An intransigent person is?','unwilling to change position or compromise','eager to accept every alternative','a person who interprets spoken language','intransigent 指不妥协的。'),Q('intransigent',2,2,'Why was the negotiator intransigent?','she rejected every compromise','she adjusted the demand after discussion','she accepted all proposals','拒绝一切折中显示不肯让步。'),Q('intransigent',3,2,'Which phrase is natural?','an intransigent opponent','an intransigent person who changes position constantly','intransigent a contract carefully','intransigent 可修饰立场强硬的人。'),Q('intransigent',4,1,'A close opposite of intransigent is?','accommodating','unyielding','inflexible','accommodating 表示愿意配合和让步。')]);
P('intrepid','intrepid derives from Latin intrepidus, “not alarmed”; it describes someone who faces danger or difficulty bravely.',C('intrepid.s1','野外考察','The intrepid surveyor crossed the flooded field to check whether the remote weather station was still operating.','这位无畏的勘测员穿过被洪水淹没的田野，去检查偏远气象站是否仍在运行。','The intrepid surveyor / crossed the flooded field / to check / whether the remote weather station was still operating.','intrepid 修饰 surveyor，突出其勇敢；to check 引出冒险前往的目的。','面对洪水仍勇敢前往检查，符合 s1。'),M('The explorer was intrepid because he refused every challenge, stayed safely at home, and avoided all danger.','The explorer was cautious and avoided danger rather than facing it bravely.','回避所有挑战与 intrepid 的勇敢无畏不符。'),[Q('intrepid',1,1,'An intrepid person?','faces danger or difficulty bravely','avoids every challenge out of fear','asks questions in a formal interview','intrepid 指勇敢无畏的。'),Q('intrepid',2,1,'Why was the surveyor intrepid?','he crossed a flooded field to reach a station','he stayed home and made no survey','he changed a date format for software','他冒险穿过洪水去执行任务。'),Q('intrepid',3,1,'Which phrase is natural?','an intrepid mountain climber','an intrepid person who never faces anything','intrepidly surveyor','intrepid 可形容勇敢的登山者。'),Q('intrepid',4,1,'A close synonym is?','fearless','timid','intermittent','fearless 与无畏的 intrepid 接近。')]);
P('intricacy','intricacy comes from intricate plus -acy and means the state or quality of having many connected details.',C('intricacy.s1','古典建筑','Visitors admired the intricacy of the carved ceiling, where hundreds of small patterns fit together without repetition.','游客赞叹雕花天花板的精巧复杂，数百个小图案彼此衔接且没有重复。','Visitors admired the intricacy / of the carved ceiling / where hundreds of small patterns / fit together without repetition.','intricacy 指复杂精细这一特征；where 从句说明细节如何构成整体。','大量细节互相衔接形成精巧复杂，符合 s1。'),M('The design had great intricacy although it contained one plain line and no connected details or patterns.','The design was simple because it had no details or patterns.','没有细节的简单线条不具备 intricacy。'),[Q('intricacy',1,1,'Intricacy is the quality of being?','detailed and complicated','plain with no connected details','between two nations only','intricacy 指精巧复杂。'),Q('intricacy',2,1,'What showed the ceiling’s intricacy?','hundreds of small patterns fitted together','one blank surface with no carving','a single straight line on a page','许多精细图案共同构成复杂设计。'),Q('intricacy',3,1,'Which phrase is natural?','the intricacy of the design','the intricacy of a blank page with no details','an intricacy quickly carved','intricacy 常与 of 连用说明复杂细节。'),Q('intricacy',4,1,'The related adjective is?','intricate','intrepid','intertidal','intricate 是形容词形式。')]);
P('intricately','intricately comes from intricate plus -ly and means in a way involving many carefully arranged details.',C('intricately.s1','手工编织','The basket was intricately woven, with thin reeds crossing in a repeated pattern around its rim.','这个篮子编织得十分精细，篮沿处的细芦苇按重复图案交错排列。','The basket was intricately woven / with thin reeds crossing / in a repeated pattern / around its rim.','intricately 修饰 woven，说明编织包含精细排列的细节；with 短语补充结构。','细芦苇按复杂图案交错，符合 s1。'),M('The basket was intricately woven even though it consisted of one flat sheet with no crossing strands or pattern.','The basket was plain and simply formed because it had no woven pattern.','没有交错结构或图案，不符合 intricately woven。'),[Q('intricately',1,1,'If an object is intricately made, it is made?','with many carefully arranged details','with no detail or arrangement','only between two cities','intricately 表示精细复杂地。'),Q('intricately',2,1,'What made the basket intricately woven?','thin reeds crossed in a repeated pattern','it was a flat unmarked sheet','the basket had no strands at all','芦苇细密交错形成图案。'),Q('intricately',3,1,'Which phrase is natural?','intricately carved wood','intricately blank surface with no carving','an intricately object','副词可修饰 carved，表示雕刻精细。'),Q('intricately',4,1,'Intricately is the adverb form of?','intricate','intimate','interstate','intricately 由 intricate 派生。')]);
P('intriguing','intriguing comes from intrigue and describes something that is unusually interesting or mysterious enough to arouse curiosity.',C('intriguing.s1','考古发现','The archaeologists found an intriguing mark beneath the paint because its shape did not match any known symbol.','考古学家发现颜料下有一道耐人寻味的痕迹，因为它的形状与已知符号都不相符。','The archaeologists found an intriguing mark / beneath the paint / because its shape / did not match any known symbol.','intriguing 修饰 mark，表示它引起好奇；because 引出谜团所在。','无法识别的符号令人想进一步调查，符合 s1。'),M('The mark was intriguing even though everyone recognized it immediately and nobody had any question about it.','The mark was familiar and ordinary because everyone recognized it at once.','没有任何未知之处、毫不引起好奇的痕迹不算 intriguing。'),[Q('intriguing',1,1,'An intriguing clue is one that?','arouses curiosity or interest','is immediately understood and raises no question','is a person answering an interview','intriguing 指引起好奇的。'),Q('intriguing',2,2,'Why did the mark intrigue archaeologists?','it matched no known symbol','it was an ordinary familiar letter','it had been removed before anyone saw it','符号形状未知，引发研究者好奇。'),Q('intriguing',3,1,'Which phrase is natural?','an intriguing possibility','an intriguing answer that raises no curiosity','intriguingly question','intriguing 可修饰 possibility。'),Q('intriguing',4,2,'Intriguing may suggest something is?','mysterious or unusually interesting','unimportant and entirely familiar','between high and low tides','神秘或特别有趣都可能引人好奇。')]);
P('intrinsically','intrinsically comes from intrinsic plus -ally and means by the nature of something itself, independent of external circumstances.',C('intrinsically.s1','伦理讨论','The committee argued that every person has intrinsically equal worth, regardless of income or social status.','委员会认为每个人本身都具有同等价值，不因收入或社会地位而异。','The committee argued / that every person has intrinsically equal worth / regardless of income / or social status.','intrinsically 修饰 equal worth，强调价值来自人的内在本质而非外部条件。','价值不受收入和地位影响，符合 s1。'),M('The committee called the worth intrinsic even though it depended entirely on income, rank, and approval from others.','The committee said the worth was externally determined by income and rank.','完全由外部地位决定的价值不是 intrinsically 固有的。'),[Q('intrinsically',1,1,'Intrinsically means?','by the nature of something itself','only because of an outside reward','at intervals with pauses','intrinsically 表示本质上、内在地。'),Q('intrinsically',2,1,'Why did the committee say worth is intrinsic?','it does not depend on income or social status','it changes with every external approval','it is measured by a bank account only','内在价值不由收入或地位决定。'),Q('intrinsically',3,1,'Which phrase is natural?','intrinsically valuable','intrinsically between two stations','intrinsicly valuable','intrinsically 可修饰 valuable。'),Q('intrinsically',4,1,'The related adjective is?','intrinsic','intriguing','interdependent','intrinsically 由 intrinsic 派生。')]);
P('introductory','introductory comes from introduce plus -ory and describes something that presents a subject or prepares newcomers at the beginning.',C('introductory.s1','大学课程','The introductory biology course covered cells and basic lab safety before students moved on to genetics.','这门生物学入门课先讲解细胞和基础实验室安全，再让学生继续学习遗传学。','The introductory biology course / covered cells and basic lab safety / before students moved on / to genetics.','introductory 修饰 course，说明课程用于初步介绍学科；before 标示进阶学习前的基础内容。','课程为初学者介绍基础，再进入进阶内容，符合 s1。'),M('The biology course was introductory although it assumed expert knowledge and began with advanced research methods for specialists only.','The biology course was advanced because it required expert knowledge from the start.','只面向专家的高阶课程不是入门课程。'),[Q('introductory',1,1,'An introductory course is designed to?','present the basics of a subject, often for newcomers','test only advanced specialists','interrupt a course halfway through','introductory 表示入门的、介绍性的。'),Q('introductory',2,1,'What did the biology course cover first?','cells and basic lab safety','advanced genetics only with no basics','a list of interview candidates','入门课程先讲基础知识和安全规范。'),Q('introductory',3,1,'Which phrase is natural?','an introductory chapter for new readers','an introductory expert-only final exam','introductory between two galaxies','introductory 可修饰为新读者准备的章节。'),Q('introductory',4,1,'Introductory is related to which verb?','introduce','intoxicate','intersect','introductory 由 introduce 派生。')]);


})();
